    14→import type { BezirkStat, Stats } from '../types/stats';
    15→
    16→ChartJS.register(CategoryScale, LinearScale, BarElement, ArcElement, PointElement, LineElement, Title, Tooltip, Legend);
    17→
    18→export default function ReportsPage() {
    19→  const { id } = useParams<{ id: string }>();
    20→  const [exercise, setExercise] = useState<any>(null);
    21→  const [stats, setStats] = useState<Stats | null>(null);
    22→  const [loading, setLoading] = useState(true);
    23→  const [showParticipants, setShowParticipants] = useState(true);
    24→  const barChartRef = useRef<any>(null);
    25→  const pieChartRef = useRef<any>(null);
