    28→  const mapCardRef = useRef<HTMLDivElement>(null);
    29→  const bezirkMapCardRef = useRef<HTMLDivElement>(null);
    30→  const pageRef = useRef<HTMLDivElement>(null);
    31→  const [exporting, setExporting] = useState(false);
    32→
    33→  const createExportHeader = () => {
    34→    const header = document.createElement('div');
    35→    header.setAttribute('data-export-inject', 'true');
    36→    header.style.cssText = 'display:flex;align-items:center;gap:12px;padding:16px 24px;background:#1e3a5f;border-radius:8px;margin-bottom:16px;';
    37→    const img = document.createElement('img');
