    44→    title.style.cssText = 'font-size:16px;font-weight:bold;color:#ffffff;letter-spacing:0.5px;';
    45→    text.appendChild(title);
    46→    const sub = document.createElement('div');
    47→    sub.textContent = 'Im Sinne der Sicherheit';
    48→    sub.style.cssText = 'font-size:10px;color:#93c5fd;letter-spacing:1px;';
    49→    text.appendChild(sub);
    50→    header.appendChild(text);
    51→    return header;
    52→  };
    53→
    54→  const createExportFooter = () => {
    55→    const footer = document.createElement('div');
    56→    footer.setAttribute('data-export-inject', 'true');
    57→    footer.style.cssText = 'text-align:center;padding:12px 0;margin-top:16px;border-top:1px solid #e5e7eb;font-size:12px;color:#6b7280;';
    58→    footer.textContent = 'oeradio.at  \u00B7  bosarsa.oeradio.at';
    59→    return footer;
    60→  };
    61→
    62→  const downloadChart = async (cardRef: React.RefObject<HTMLDivElement | null>, filename: string) => {
    63→    if (!cardRef.current || !exercise) return;
    64→    setExporting(true);
    65→    const header = createExportHeader();
    66→    const footer = createExportFooter();
    67→    // Wrap the card temporarily
    68→    const wrapper = document.createElement('div');
    69→    wrapper.style.cssText = 'padding:24px;background:#f3f4f6;';
    70→    const parent = cardRef.current.parentNode!;
    71→    const next = cardRef.current.nextSibling;
    72→    parent.insertBefore(wrapper, cardRef.current);
    73→    wrapper.appendChild(header);
    74→    wrapper.appendChild(cardRef.current);
    75→    wrapper.appendChild(footer);
    76→    try {
    77→      const url = await toPng(wrapper, { backgroundColor: '#f3f4f6', pixelRatio: 2 });
    78→      const link = document.createElement('a');
    79→      link.download = filename;
    80→      link.href = url;
    81→      link.click();
    82→    } catch {} finally {
    83→      // Move card back to original position
    84→      if (next) parent.insertBefore(cardRef.current, next); else parent.appendChild(cardRef.current);
    85→      wrapper.remove();
    86→      setExporting(false);
    87→    }
    88→  };
    89→
    90→  const downloadFullPage = async () => {
    91→    if (!exercise) return;
    92→    setExporting(true);
    93→    try {
    94→      const token = localStorage.getItem('token');
    95→      const res = await fetch(`/api/v1/pdf/exercises/${id}`, {
    96→        headers: token ? { Authorization: `Bearer ${token}` } : {},
    97→      });
    98→      if (!res.ok) throw new Error();
    99→      const blob = await res.blob();
   100→      const url = URL.createObjectURL(blob);
   101→      const link = document.createElement('a');
   102→      link.href = url;
   103→      link.download = `BOS-ARSA_Auswertung_${exercise.date}.pdf`;
   104→      link.click();
   105→      URL.revokeObjectURL(url);
   106→    } catch {} finally {
   107→      setExporting(false);
   108→    }
   109→  };
   110→
   111→  useEffect(() => {
   112→    if (!id) return;
   113→    Promise.all([
   114→      apiFetch(`/api/v1/exercises/${id}`),
   115→      apiFetch(`/api/v1/exercises/${id}/stats`),
   116→    ]).then(([ex, st]) => {
   117→      setExercise(ex);
   118→      setStats(st);
   119→    }).catch(() => {}).finally(() => setLoading(false));
   120→  }, [id]);
   121→
   122→  if (loading) return <p className="text-gray-500">Laden...</p>;
   123→  if (!exercise) return <p className="text-red-500">Nicht gefunden</p>;
   124→
   125→  // Group bezirk stats by Bundesland
   126→  const byBl: Record<string, { name: string; bezirke: BezirkStat[]; totalParticipants: number; totalReports: number }> = {};
   127→  if (stats) {
   128→    for (const bz of stats.bezirkStats) {
   129→      if (!byBl[bz.bundesland_code]) {
   130→        byBl[bz.bundesland_code] = { name: bz.bundesland, bezirke: [], totalParticipants: 0, totalReports: 0 };
   131→      }
   132→      byBl[bz.bundesland_code].bezirke.push(bz);
   133→      byBl[bz.bundesland_code].totalParticipants += bz.participants;
   134→      byBl[bz.bundesland_code].totalReports += bz.reports;
   135→    }
   136→  }
   137→
   138→  const formatDate = (d: string) => {
   139→    const date = new Date(d + 'T00:00:00');
   140→    return date.toLocaleDateString('de-AT', { weekday: 'long', day: '2-digit', month: '2-digit', year: 'numeric' });
   141→  };
   142→
   143→  return (
   144→    <div ref={pageRef} className="space-y-6">
   145→      <div className="flex items-center justify-between gap-2">
   146→        <div className="min-w-0">
   147→          <h1 className="text-base sm:text-xl font-bold text-[#1e3a5f]">Auswertung</h1>
   148→          <p className="text-xs sm:text-sm text-gray-500 truncate">{exercise.name} — {formatDate(exercise.date)}</p>
   149→        </div>
   150→        <div className="flex items-center gap-2 flex-shrink-0" data-no-export="true">
   151→          <button
   152→            onClick={downloadFullPage}
   153→            disabled={exporting}
   154→            className="bg-[#1e3a5f] hover:bg-[#2a4a7f] text-white px-2 sm:px-3 py-1.5 rounded text-xs sm:text-sm disabled:opacity-50"
   155→          >
   156→            {exporting ? 'Exportieren...' : 'Download Auswertung'}
   157→          </button>
   158→          <Link to={`/exercises/${id}`} className="bg-gray-200 hover:bg-gray-300 text-gray-700 px-2 sm:px-3 py-1.5 rounded text-xs sm:text-sm">
   159→            Zurück
   160→          </Link>
   161→        </div>
   162→      </div>
   163→
   164→      {stats && (
   165→        <>
   166→          {/* Summary cards */}
   167→          <div className="grid grid-cols-2 md:grid-cols-4 gap-2 sm:gap-3">
   168→            <div className="bg-white rounded-lg shadow-sm p-2 sm:p-4 text-center">
   169→              <div className="text-2xl sm:text-3xl font-bold text-[#1e3a5f]">{stats.totalParticipants}</div>
   170→              <div className="text-xs sm:text-sm text-gray-500">Teilnehmer</div>
   171→            </div>
   172→            <div className="bg-white rounded-lg shadow-sm p-2 sm:p-4 text-center">
   173→              <div className="text-2xl sm:text-3xl font-bold text-[#1e3a5f]">{stats.totalReports}</div>
   174→              <div className="text-xs sm:text-sm text-gray-500">Rapporte</div>
   175→            </div>
   176→            {stats.perRepeater.map((r) => (
   177→              <div key={r.short_name} className="bg-white rounded-lg shadow-sm p-2 sm:p-4 text-center">
   178→                <div className="text-xl sm:text-2xl font-bold text-gray-700">{r.count}</div>
   179→                <div className="text-xs text-gray-500 truncate">{r.short_name}</div>
   180→              </div>
   181→            ))}
   182→          </div>
   183→
   184→          {/* Austria Map */}
   185→          {stats.blStats.length > 0 && (
   186→            <div ref={mapCardRef} className="bg-white rounded-xl shadow p-3 sm:p-4">
   187→              <div className="flex items-center justify-between mb-2 sm:mb-3">
   188→                <h2 className="text-xs sm:text-sm font-semibold text-[#1e3a5f]">
   189→                  Teilnehmer nach Bundesland / Land
   190→                </h2>
   191→                <button
   192→                  onClick={() => downloadChart(mapCardRef, `BOS-ARSA_Karte_${exercise.date}.png`)}
