    25→}
    26→
    27→interface AggregatedResponse {
    28→  exercises: ExerciseSummary[];
    29→  stats: Stats;
    30→}
    31→
    32→const PIE_COLORS = [
    33→  '#1e3a5f', '#c8102e', '#d97706', '#0d6efd', '#198754',
    34→  '#6f42c1', '#fd7e14', '#20c997', '#0dcaf0', '#6c757d',
    35→  '#2c5282', '#e8a317', '#c70039', '#4361ee', '#2d6a4f',
    36→  '#9b59b6', '#e67e22', '#1abc9c', '#3498db', '#95a5a6',
    37→];
    38→
    39→function formatDateDE(d: string) {
    40→  const date = new Date(d + 'T00:00:00');
    41→  return date.toLocaleDateString('de-AT', { day: '2-digit', month: '2-digit', year: 'numeric' });
    42→}
    43→
    44→function toISO(d: Date) {
    45→  return d.toISOString().slice(0, 10);
    46→}
    47→
    48→export default function AggregatedReportsPage() {
    49→  const now = new Date();
    50→  const year = now.getFullYear();
    51→
    52→  const [from, setFrom] = useState(() => toISO(new Date(year, 0, 1)));
    53→  const [to, setTo] = useState(() => toISO(new Date(year, 11, 31)));
    54→  const [data, setData] = useState<AggregatedResponse | null>(null);
    55→  const [loading, setLoading] = useState(false);
    56→  const [showExercises, setShowExercises] = useState(false);
    57→  const [showParticipants, setShowParticipants] = useState(true);
    58→  const [exporting, setExporting] = useState(false);
    59→  const [selectedTypes, setSelectedTypes] = useState<Set<string>>(new Set());
    60→
    61→  const barChartRef = useRef<any>(null);
    62→  const pieChartRef = useRef<any>(null);
    63→  const barCardRef = useRef<HTMLDivElement>(null);
    64→  const pieCardRef = useRef<HTMLDivElement>(null);
    65→  const mapCardRef = useRef<HTMLDivElement>(null);
    66→  const bezirkMapCardRef = useRef<HTMLDivElement>(null);
    67→  const pageRef = useRef<HTMLDivElement>(null);
    68→
    69→  const fetchStats = (f: string, t: string, types?: Set<string>) => {
    70→    setLoading(true);
    71→    const typesParam = types && types.size > 0 ? `&types=${Array.from(types).map(encodeURIComponent).join(',')}` : '';
    72→    apiFetch(`/api/v1/reports/stats?from=${f}&to=${t}${typesParam}`)
    73→      .then((res) => setData(res))
    74→      .catch(() => setData(null))
    75→      .finally(() => setLoading(false));
    76→  };
    77→
    78→  useEffect(() => {
    79→    fetchStats(from, to, selectedTypes);
    80→  }, []);
    81→
    82→  const applyRange = (f: string, t: string) => {
    83→    setFrom(f);
    84→    setTo(t);
    85→    fetchStats(f, t, selectedTypes);
    86→  };
    87→
    88→  const applyQuarter = (q: number) => {
    89→    const start = new Date(year, (q - 1) * 3, 1);
    90→    const end = new Date(year, q * 3, 0);
    91→    applyRange(toISO(start), toISO(end));
    92→  };
    93→
    94→  const applyYear = () => {
    95→    applyRange(toISO(new Date(year, 0, 1)), toISO(new Date(year, 11, 31)));
    96→  };
    97→
    98→  const handleFromChange = (v: string) => {
    99→    setFrom(v);
   100→    fetchStats(v, to, selectedTypes);
   101→  };
   102→
   103→  const handleToChange = (v: string) => {
   104→    setTo(v);
   105→    fetchStats(from, v, selectedTypes);
   106→  };
   107→
   108→  const toggleType = (type: string) => {
   109→    setSelectedTypes(prev => {
   110→      const next = new Set(prev);
   111→      if (next.has(type)) next.delete(type);
   112→      else next.add(type);
   113→      fetchStats(from, to, next);
   114→      return next;
   115→    });
   116→  };
   117→
   118→  const createExportHeader = () => {
   119→    const header = document.createElement('div');
   120→    header.setAttribute('data-export-inject', 'true');
   121→    header.style.cssText = 'display:flex;align-items:center;gap:12px;padding:16px 24px;background:#1e3a5f;border-radius:8px;margin-bottom:16px;';
   122→    const img = document.createElement('img');
   123→    img.src = '/bosarsa.webp';
   124→    img.style.cssText = 'height:36px;border-radius:4px;';
   125→    header.appendChild(img);
   126→    const text = document.createElement('div');
   127→    const title = document.createElement('div');
   128→    title.textContent = 'BOS-ARSA Log';
   129→    title.style.cssText = 'font-size:16px;font-weight:bold;color:#ffffff;letter-spacing:0.5px;';
   130→    text.appendChild(title);
   131→    const sub = document.createElement('div');
   132→    sub.textContent = 'Im Sinne der Sicherheit';
   133→    sub.style.cssText = 'font-size:10px;color:#93c5fd;letter-spacing:1px;';
   134→    text.appendChild(sub);
   135→    header.appendChild(text);
   136→    return header;
   137→  };
   138→
   139→  const createExportFooter = () => {
   140→    const footer = document.createElement('div');
   141→    footer.setAttribute('data-export-inject', 'true');
   142→    footer.style.cssText = 'text-align:center;padding:12px 0;margin-top:16px;border-top:1px solid #e5e7eb;font-size:12px;color:#6b7280;';
   143→    footer.textContent = 'oeradio.at  \u00B7  bosarsa.oeradio.at';
   144→    return footer;
   145→  };
   146→
   147→  const downloadChart = async (cardRef: React.RefObject<HTMLDivElement | null>, filename: string) => {
   148→    if (!cardRef.current) return;
   149→    setExporting(true);
   150→    const header = createExportHeader();
   151→    const footer = createExportFooter();
   152→    const wrapper = document.createElement('div');
   153→    wrapper.style.cssText = 'padding:24px;background:#f3f4f6;';
   154→    const parent = cardRef.current.parentNode!;
   155→    const next = cardRef.current.nextSibling;
   156→    parent.insertBefore(wrapper, cardRef.current);
   157→    wrapper.appendChild(header);
   158→    wrapper.appendChild(cardRef.current);
   159→    wrapper.appendChild(footer);
   160→    try {
   161→      const url = await toPng(wrapper, { backgroundColor: '#f3f4f6', pixelRatio: 2 });
   162→      const link = document.createElement('a');
   163→      link.download = filename;
   164→      link.href = url;
   165→      link.click();
   166→    } catch {} finally {
   167→      if (next) parent.insertBefore(cardRef.current, next); else parent.appendChild(cardRef.current);
   168→      wrapper.remove();
   169→      setExporting(false);
   170→    }
   171→  };
   172→
   173→  const downloadFullPage = async () => {
   174→    setExporting(true);
   175→    try {
   176→      const token = localStorage.getItem('token');
   177→      const typesParam = selectedTypes.size > 0 ? `&types=${Array.from(selectedTypes).map(encodeURIComponent).join(',')}` : '';
   178→      const res = await fetch(`/api/v1/pdf/reports?from=${from}&to=${to}${typesParam}`, {
   179→        headers: token ? { Authorization: `Bearer ${token}` } : {},
   180→      });
   181→      if (!res.ok) throw new Error();
   182→      const blob = await res.blob();
   183→      const url = URL.createObjectURL(blob);
   184→      const link = document.createElement('a');
   185→      link.href = url;
   186→      link.download = `BOS-ARSA_Auswertung_${from}_${to}.pdf`;
   187→      link.click();
   188→      URL.revokeObjectURL(url);
   189→    } catch {} finally {
   190→      setExporting(false);
   191→    }
   192→  };
   193→
   194→  const stats = data?.stats ?? null;
   195→  const exercises = data?.exercises ?? [];
