   370→                        const newCodes = isActive ? codes.filter((c: string) => c !== bl.code) : [...codes, bl.code];
   371→                        const val = newCodes.length > 0 ? newCodes.sort().join(',') : null;
   372→                        await withSave(async () => {
   373→                          await apiFetch(`/api/v1/exercises/${id}`, {
   374→                            method: 'PATCH',
   375→                            body: JSON.stringify({ simplex_bl_codes: val }),
   376→                          });
   377→                          setExercise((prev: any) => prev ? { ...prev, simplex_bl_codes: val } : null);
   378→                        });
   379→                      }}
   380→                      className={`flex flex-col items-center py-1.5 px-1 rounded border transition-colors text-xs ${
   381→                        isActive
   382→                          ? 'border-red-500 bg-red-50 text-[#1e3a5f] font-semibold'
   383→                          : 'border-gray-200 bg-gray-50 text-gray-400 hover:border-gray-300'
   384→                      }`}
   385→                    >
   386→                      <span>{bl.label}</span>
   387→                    </button>
   388→                  );
   389→                })}
   390→              </div>
   391→            </div>
   392→          )}
   393→        </div>
   394→      )}
   395→
   396→      {/* Bundesländer selection */}
   397→      <div className="bg-white rounded-xl shadow p-3 sm:p-4">
   398→        <h2 className="text-base sm:text-lg font-semibold text-[#1e3a5f] mb-2 sm:mb-3">Bundesländer auswählen</h2>
   399→        <div className="grid grid-cols-3 sm:grid-cols-5 lg:grid-cols-9 gap-2">
   400→          {BUNDESLAENDER.map(bl => {
   401→            const isActive = activeBundeslaender.has(bl.code);
   402→            const repCount = repeatersForBl(bl.code).length;
   403→            const activeCount = activeRepeaters.filter(ar => {
   404→              const rep = allRepeaters.find(r => r.id === ar.repeater_id);
   405→              return rep?.bundesland_code === bl.code && !rep?.is_linked;
   406→            }).length;
   407→            return (
   408→              <button
   409→                key={bl.code}
   410→                onClick={() => isAdmin && toggleBundesland(bl.code)}
   411→                disabled={!isAdmin}
   412→                className={`flex flex-col items-center py-2 px-1 rounded-lg border-2 transition-colors text-sm ${
   413→                  isActive
   414→                    ? 'border-red-500 bg-red-50 text-[#1e3a5f]'
   415→                    : 'border-gray-200 bg-gray-50 text-gray-500 hover:border-gray-300'
   416→                } ${!isAdmin ? 'cursor-default' : ''}`}
   417→              >
   418→                <span className="font-bold">{bl.label}</span>
   419→                <span className="text-xs truncate w-full text-center">{bl.name}</span>
   420→                {isActive && <span className="text-xs mt-0.5">{activeCount}/{repCount}</span>}
   421→              </button>
   422→            );
   423→          })}
   424→        </div>
   425→      </div>
   426→
   427→      {/* Per-Bundesland repeater sections */}
   428→      {BUNDESLAENDER.filter(bl => activeBundeslaender.has(bl.code)).map(bl => {
   429→        const blRepeaters = repeatersForBl(bl.code);
   430→        const isExpanded = expandedBl.has(bl.code);
   431→
   432→        return (
   433→          <div key={bl.code} className="bg-white rounded-xl shadow overflow-hidden">
   434→            <button
   435→              onClick={() => toggleExpanded(bl.code)}
   436→              className="w-full flex items-center justify-between p-4 hover:bg-gray-50 transition-colors"
   437→            >
   438→              <div className="flex items-center gap-2">
   439→                <span className="font-bold text-[#1e3a5f]">{bl.label}</span>
   440→                <span className="font-semibold text-[#1e3a5f]">{bl.name}</span>
   441→                <span className="text-xs bg-red-100 text-red-800 px-2 py-0.5 rounded-full">
   442→                  {activeRepeaters.filter(ar => {
   443→                    const rep = allRepeaters.find(r => r.id === ar.repeater_id);
   444→                    return rep?.bundesland_code === bl.code;
   445→                  }).length} / {blRepeaters.length}
   446→                </span>
   447→              </div>
   448→              <span className="text-gray-400">{isExpanded ? '▲' : '▼'}</span>
   449→            </button>
   450→
   451→            {isExpanded && (
   452→              <div className="border-t px-4 pb-4">
   453→                <div className="space-y-1 mt-2">
   454→                  {blRepeaters.map(rep => {
   455→                    const active = activeRepeaters.find(r => r.repeater_id === rep.id);
   456→                    return (
   457→                      <div key={rep.id} className="flex items-center gap-3 py-2 border-b border-gray-100">
   458→                        <label className={`flex items-center gap-1.5 sm:gap-2 flex-1 flex-wrap ${!active || isAdmin ? 'cursor-pointer' : 'cursor-default'}`}>
   459→                          <input
   460→                            type="checkbox"
   461→                            checked={!!active}
   462→                            disabled={!!active && !isAdmin}
   463→                            onChange={() => toggleRepeater(rep.id)}
   464→                            className="w-4 h-4 accent-red-600 flex-shrink-0"
   465→                          />
   466→                          <span className="font-medium text-xs sm:text-sm">{rep.short_name}{rep.callsign ? ` (${rep.callsign})` : ''}</span>
   467→                          <span className="text-xs text-gray-500 hidden sm:inline">
   468→                            {rep.frequency_mhz && `${rep.frequency_mhz} MHz`}
   469→                          </span>
   470→                          {rep.ctcss_hz && <span className="text-xs text-gray-400 hidden md:inline">CTCSS {rep.ctcss_hz}</span>}
   471→                          {rep.is_linked ? <span className="text-xs bg-blue-100 text-blue-700 px-1.5 py-0.5 rounded">oelink</span> : null}
   472→                          {rep.is_custom ? <span className="text-xs bg-purple-100 text-purple-700 px-1.5 py-0.5 rounded">custom</span> : null}
   473→                        </label>
   474→                      </div>
   475→                    );
   476→                  })}
   477→                </div>
