   490→                      <button onClick={() => addCustomRepeater(bl.code)} className="bg-[#c8102e] hover:bg-[#a00d24] text-white px-3 py-1 rounded text-sm">Hinzufügen</button>
   491→                      <button onClick={() => setShowAddForm(null)} className="text-gray-500 text-sm hover:text-gray-700">Abbrechen</button>
   492→                    </div>
   493→                  </div>
   494→                ) : (
   495→                  <button onClick={() => setShowAddForm(bl.code)} className="mt-2 text-sm text-red-700 hover:text-red-900 font-medium">
   496→                    + Umsetzer hinzufügen
   497→                  </button>
   498→                )}
   499→              </div>
   500→            )}
   501→          </div>
   502→        );
   503→      })}
   504→
   505→      {/* Simplex frequencies */}
   506→      <div className="bg-white rounded-xl shadow overflow-hidden">
   507→        <div className="p-4">
   508→          <h2 className="text-lg font-semibold text-[#1e3a5f] mb-3">Simplex-Frequenzen</h2>
   509→          <div className="space-y-1">
   510→            {simplexRepeaters.map(rep => {
   511→              const active = activeRepeaters.find(r => r.repeater_id === rep.id);
   512→              return (
   513→                <div key={rep.id} className="flex items-center gap-3 py-2 border-b border-gray-100">
   514→                  <label className={`flex items-center gap-2 flex-1 ${!active || isAdmin ? 'cursor-pointer' : 'cursor-default'}`}>
   515→                    <input
   516→                      type="checkbox"
   517→                      checked={!!active}
   518→                      disabled={!!active && !isAdmin}
   519→                      onChange={() => toggleRepeater(rep.id)}
   520→                      className="w-4 h-4 accent-red-600"
   521→                    />
   522→                    <span className="font-medium text-sm">{rep.short_name}</span>
   523→                    <span className="text-xs text-gray-500">
   524→                      {rep.frequency_mhz && `${rep.frequency_mhz} MHz`}
   525→                    </span>
   526→                    {rep.is_custom ? <span className="text-xs bg-purple-100 text-purple-700 px-1.5 py-0.5 rounded">custom</span> : null}
   527→                  </label>
   528→                </div>
   529→              );
   530→            })}
   531→          </div>
   532→
   533→          {/* Add custom simplex */}
   534→          {showAddForm === 'simplex' ? (
   535→            <div className="mt-3 p-3 bg-gray-50 rounded-lg space-y-2">
   536→              <div className="flex gap-2 flex-wrap">
   537→                <input type="text" placeholder="Name (optional)" value={newRepName} onChange={e => setNewRepName(e.target.value)} className="border rounded px-2 py-1 text-sm flex-1 min-w-[120px]" />
   538→                <input type="text" placeholder="Frequenz MHz" value={newRepFreq} onChange={e => setNewRepFreq(e.target.value)} className="border rounded px-2 py-1 text-sm w-28" />
   539→              </div>
   540→              <div className="flex gap-2">
   541→                <button onClick={() => addCustomRepeater(null)} className="bg-[#c8102e] hover:bg-[#a00d24] text-white px-3 py-1 rounded text-sm">Hinzufügen</button>
   542→                <button onClick={() => setShowAddForm(null)} className="text-gray-500 text-sm hover:text-gray-700">Abbrechen</button>
   543→              </div>
   544→            </div>
   545→          ) : (
   546→            <button onClick={() => setShowAddForm('simplex')} className="mt-2 text-sm text-red-700 hover:text-red-900 font-medium">
   547→              + Simplex-Frequenz hinzufügen
   548→            </button>
   549→          )}
   550→        </div>
   551→      </div>
   552→
   553→      {/* Delete confirmation modal */}
   554→      {showDeleteConfirm && (
   555→        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
   556→          <div className="bg-white rounded-xl shadow-xl max-w-md w-full p-6">
