   478→
   479→function BezirkRow({ bezirk, reports, availableBezirke, allBezirke, allBundeslaender, linkedRepeaters, defaultRepeaterId, onSubmit, onEdit, onDelete, onMoveToBezirk, editingId, editForm, onEditChange, onEditSave, onEditCancel, dragReportId, onDragStart, onDragEnd }: BezirkRowProps) {
   480→  const [form, setForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '5/9', notes: '', opName: '', opQth: '', bezirkCode: '', suffix: '' });
   481→  const [repeaterId, setRepeaterId] = useState(defaultRepeaterId);
   482→  const [dragOver, setDragOver] = useState(false);
   483→  const callsignRef = useRef<CallsignInputRef>(null);
   484→  const rapportRef = useRef<HTMLInputElement>(null);
   485→
   486→  useEffect(() => {
   487→    if (defaultRepeaterId && !repeaterId) setRepeaterId(defaultRepeaterId);
   488→  }, [defaultRepeaterId]);
   489→
   490→  const handleSubmit = (e: FormEvent) => {
   491→    e.preventDefault();
   492→    if (!form.callsign && !form.operator) return;
   493→    if (!repeaterId) return;
   494→    onSubmit(repeaterId, form);
   495→    setForm({ callsign: '', operator: null, rapport: '5/9', notes: '', opName: '', opQth: '', bezirkCode: '', suffix: '' });
   496→    setTimeout(() => callsignRef.current?.focus(), 50);
   497→  };
   498→
   499→  const handleDrop = (e: React.DragEvent) => {
   500→    e.preventDefault();
   501→    setDragOver(false);
   502→    if (dragReportId) {
   503→      const targetCode = bezirk.code === '??' ? null : bezirk.code;
   504→      onMoveToBezirk(dragReportId, targetCode);
   505→    }
   506→  };
   507→
   508→  const saveOperatorField = (field: 'name' | 'qth', value: string) => {
   509→    if (!form.operator?.id) return;
   510→    const original = field === 'name' ? (form.operator.name || '') : (form.operator.qth || '');
   511→    if (value === original) return;
   512→    apiFetch(`/api/v1/operators/${form.operator.id}`, {
   513→      method: 'PATCH',
   514→      body: JSON.stringify({ [field]: value || null }),
   515→    }).then(() => {
   516→      setForm(f => ({ ...f, operator: { ...f.operator, [field]: value || null } }));
   517→    }).catch(() => {});
   518→  };
   519→
   520→  return (
   521→    <div
   522→      className={`px-2 sm:px-3 py-1.5 transition-colors ${dragOver && dragReportId ? 'bg-blue-100 ring-2 ring-blue-400 ring-inset' : ''}`}
   523→      onDragOver={e => { if (dragReportId) { e.preventDefault(); setDragOver(true); } }}
   524→      onDragLeave={() => setDragOver(false)}
   525→      onDrop={handleDrop}
   526→    >
   527→      <div className="flex items-center gap-1.5 sm:gap-2 mb-1">
   528→        <span className={`text-xs font-mono px-1.5 py-0.5 rounded text-white ${bezirk.code === '??' ? 'bg-[#ffc107] text-gray-800' : bezirk.is_capital ? 'bg-[#dc3545]' : 'bg-[#6c757d]'}`}>
   529→          {bezirk.code === '??' ? '??' : bezirk.code}
   530→        </span>
   531→        <span className="text-xs text-gray-500 truncate">{bezirk.name}</span>
   532→        {reports.length > 0 && <span className="text-xs text-gray-400 flex-shrink-0">({reports.length})</span>}
   533→      </div>
   534→
   535→      {reports.length > 0 && (
   536→        <table className="w-full text-xs mb-1">
   537→          <tbody>
   538→            {reports.map((r, idx) => (
   539→              <tr
   540→                key={r.id}
   541→                className={`hover:bg-blue-50 group ${dragReportId === r.id ? 'opacity-40' : ''}`}
   542→                draggable={editingId !== r.id}
   543→                onDragStart={e => { e.dataTransfer.effectAllowed = 'move'; onDragStart(r.id); }}
   544→                onDragEnd={onDragEnd}
   545→              >
   546→                {editingId === r.id ? (
   547→                  <td colSpan={6} className="py-0.5">
   548→                    <div className="flex items-center gap-1 bg-blue-50 rounded p-1 flex-wrap" onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); onEditSave(); } }}>
   549→                      <span className="font-mono font-medium">{r.callsign}</span>
   550→                      <input value={editForm.opName} onChange={e => onEditChange({ ...editForm, opName: e.target.value })} placeholder="Name" className="border rounded px-1 py-0.5 text-xs w-16 sm:w-20 hidden sm:block" />
   551→                      <input value={editForm.opQth} onChange={e => onEditChange({ ...editForm, opQth: e.target.value })} placeholder="QTH" className="border rounded px-1 py-0.5 text-xs w-14 sm:w-16 hidden sm:block" />
   552→                      <input value={editForm.rapport} onChange={e => onEditChange({ ...editForm, rapport: e.target.value.toUpperCase() })} className="border rounded px-1 py-0.5 font-mono text-xs w-16 sm:w-20" autoFocus />
   553→                      <input value={editForm.notes} onChange={e => onEditChange({ ...editForm, notes: e.target.value })} placeholder="Sonst." className="border rounded px-1 py-0.5 text-xs w-16 sm:w-20" />
   554→                      <select
   555→                        value={editForm.bezirkCode}
   556→                        onChange={e => onEditChange({ ...editForm, bezirkCode: e.target.value })}
   557→                        className="border rounded px-1 py-0.5 text-xs w-20 sm:w-24"
   558→                        title="Bezirk"
   559→                      >
   560→                        <option value="">??</option>
