   584→                    <td className="py-0.5 font-mono text-gray-500 w-16 sm:w-24 cursor-pointer" onClick={() => onEdit(r)}>
   585→                      {r.readability && r.strength ? `${r.readability}/${r.strength}${r.db_over_s9 || ''}` : '—'}
   586→                    </td>
   587→                    <td className="py-0.5 text-gray-500 cursor-pointer hidden sm:table-cell" onClick={() => onEdit(r)}>{r.notes || ''}</td>
   588→                    <td className="py-0.5 w-4">
   589→                      <button onClick={() => onDelete(r.id)} className="text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100">x</button>
   590→                    </td>
   591→                  </>
   592→                )}
   593→              </tr>
   594→            ))}
   595→          </tbody>
   596→        </table>
   597→      )}
   598→
   599→      <form onSubmit={handleSubmit} className="flex items-center gap-1">
   600→        {linkedRepeaters.length > 0 && (
   601→          <select
   602→            value={repeaterId || ''}
   603→            onChange={e => setRepeaterId(parseInt(e.target.value))}
   604→            className="border border-gray-300 rounded px-1 py-0.5 text-xs max-w-[80px] sm:max-w-none focus:outline-none focus:ring-1 focus:ring-blue-500"
   605→          >
   606→            {linkedRepeaters.map(r => (
   607→              <option key={r.id} value={r.id}>
   608→                {r.site_name || r.short_name}{r.callsign ? ` (${r.callsign})` : ''}
   609→              </option>
   610→            ))}
   611→          </select>
   612→        )}
   613→        <CallsignInput
   614→          ref={callsignRef}
   615→          value={form.callsign}
   616→          onChange={v => setForm(f => ({ ...f, callsign: v, operator: null, opName: '', opQth: '' }))}
   617→          onSelect={op => {
   618→            setForm(f => ({ ...f, operator: op, callsign: op.callsign, opName: op.name || '', opQth: op.qth || '' }));
   619→            setTimeout(() => { const el = rapportRef.current; if (el) { el.focus(); el.setSelectionRange(el.value.length, el.value.length); } }, 50);
   620→          }}
   621→          onEnter={() => setTimeout(() => { const el = rapportRef.current; if (el) { el.focus(); el.setSelectionRange(el.value.length, el.value.length); } }, 50)}
   622→          className="w-24 sm:w-28"
   623→        />
   624→        <div className="flex gap-0.5">
   625→          {SUFFIXES.map(s => (
   626→            <button
