   630→              className={`px-1 py-0.5 rounded text-xs font-mono border ${form.suffix === s ? 'bg-blue-600 text-white border-blue-600' : 'bg-gray-100 text-gray-600 border-gray-300 hover:bg-gray-200'}`}
   631→              title={s}
