      ) : (
        <BundMode
          exerciseId={id!}
          reports={reports}
          onReportCreated={handleReportCreated}
          onReportUpdated={handleReportUpdated}
          onReportDeleted={handleReportDeleted}
        />
      )}

      {showImport && (
        <EmHamImport
          exerciseId={id!}
          onClose={() => setShowImport(false)}
          onImported={(importedReports) => {
