        <h1 className="text-xl sm:text-2xl font-bold text-[#1e3a5f]">Rufzeichen-Register</h1>
        <button onClick={() => setShowAdd(true)} className="bg-[#c8102e] hover:bg-[#a00d24] text-white px-2 sm:px-3 py-1.5 rounded text-sm flex-shrink-0">
          + Neu
        </button>
      </div>

      <div className="flex items-center gap-3">
        <input
          type="text"
          value={search}
          onChange={e => handleSearch(e.target.value)}
          placeholder="Rufzeichen, Name oder QTH suchen..."
          className="flex-1 border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
          autoFocus
        />
        <span className="text-sm text-gray-500">{total} Einträge</span>
      </div>

      {showAdd && (
        <div className="bg-white rounded-lg shadow p-4 space-y-2">
          <h3 className="font-medium text-sm">Neues Rufzeichen anlegen</h3>
          <div className="flex gap-2 flex-wrap">
            <input value={newOp.callsign} onChange={e => setNewOp(p => ({ ...p, callsign: e.target.value.toUpperCase() }))} placeholder="Rufzeichen" className="border rounded px-2 py-1 text-sm font-mono uppercase w-28" />
            <input value={newOp.name} onChange={e => setNewOp(p => ({ ...p, name: e.target.value }))} placeholder="Name" className="border rounded px-2 py-1 text-sm w-32" />
            <input value={newOp.qth} onChange={e => setNewOp(p => ({ ...p, qth: e.target.value }))} placeholder="QTH" className="border rounded px-2 py-1 text-sm w-32" />
            <input value={newOp.bezirk_code} onChange={e => setNewOp(p => ({ ...p, bezirk_code: e.target.value.toUpperCase() }))} placeholder="Bezirk" className="border rounded px-2 py-1 text-sm w-16 uppercase" />
            <input value={newOp.bundesland_code} onChange={e => setNewOp(p => ({ ...p, bundesland_code: e.target.value }))} placeholder="BL" className="border rounded px-2 py-1 text-sm w-12" />
            <button onClick={handleAdd} className="bg-green-600 text-white px-3 py-1 rounded text-sm">Anlegen</button>
            <button onClick={() => setShowAdd(false)} className="text-gray-500 text-sm">Abbrechen</button>
          </div>
        </div>
      )}

      <div className="bg-white rounded-xl shadow overflow-x-auto">
        <table className="w-full text-sm min-w-[400px]">
          <thead className="bg-[#1e3a5f] text-white">
            <tr>
              <th className="px-2 sm:px-3 py-2 text-left">Rufzeichen</th>
              <th className="px-2 sm:px-3 py-2 text-left">Name</th>
              <th className="px-2 sm:px-3 py-2 text-left hidden sm:table-cell">QTH</th>
              <th className="px-2 sm:px-3 py-2 text-left">Bezirk</th>
              <th className="px-2 sm:px-3 py-2 text-left hidden sm:table-cell">BL</th>
              <th className="px-2 sm:px-3 py-2 text-left hidden md:table-cell">Ausstattung</th>
              <th className="px-2 sm:px-3 py-2"></th>
            </tr>
          </thead>
          <tbody>
            {operators.map(op => (
              <tr key={op.id} className="border-t hover:bg-blue-50">
                {editing?.id === op.id ? (
                  <>
                    <td className="px-3 py-1"><input value={editing.callsign} onChange={e => setEditing({ ...editing, callsign: e.target.value.toUpperCase() })} className="border rounded px-1 py-0.5 font-mono text-xs w-24 uppercase" /></td>
                    <td className="px-3 py-1"><input value={editing.name || ''} onChange={e => setEditing({ ...editing, name: e.target.value })} className="border rounded px-1 py-0.5 text-xs w-24" /></td>
                    <td className="px-3 py-1"><input value={editing.qth || ''} onChange={e => setEditing({ ...editing, qth: e.target.value })} className="border rounded px-1 py-0.5 text-xs w-24" /></td>
                    <td className="px-3 py-1"><input value={editing.bezirk_code || ''} onChange={e => setEditing({ ...editing, bezirk_code: e.target.value.toUpperCase() })} className="border rounded px-1 py-0.5 text-xs w-12 uppercase" /></td>
                    <td className="px-3 py-1"><input value={editing.bundesland_code || ''} onChange={e => setEditing({ ...editing, bundesland_code: e.target.value })} className="border rounded px-1 py-0.5 text-xs w-10" /></td>
                    <td className="px-3 py-1"><input value={editing.equipment || ''} onChange={e => setEditing({ ...editing, equipment: e.target.value })} className="border rounded px-1 py-0.5 text-xs w-24" /></td>
                    <td className="px-3 py-1 flex gap-1">
                      <button onClick={() => handleSave(editing)} className="text-green-600 text-xs font-bold">OK</button>
                      <button onClick={() => setEditing(null)} className="text-gray-400 text-xs">X</button>
                    </td>
                  </>
                ) : (
                  <>
                    <td className="px-2 sm:px-3 py-1.5 font-mono font-medium">{op.callsign}</td>
                    <td className="px-2 sm:px-3 py-1.5">{op.name}</td>
                    <td className="px-2 sm:px-3 py-1.5 text-gray-500 hidden sm:table-cell">{op.qth}</td>
                    <td className="px-2 sm:px-3 py-1.5">
                      {op.bezirk_code && (
                        <span className="text-xs bg-gray-200 rounded px-1">{op.bezirk_code}</span>
                      )}
                    </td>
                    <td className="px-2 sm:px-3 py-1.5 text-gray-500 hidden sm:table-cell">{op.bundesland_code}</td>
                    <td className="px-2 sm:px-3 py-1.5 text-xs text-gray-400 hidden md:table-cell">{op.equipment}</td>
                    <td className="px-2 sm:px-3 py-1.5 flex gap-2">
                      <button onClick={() => setEditing({ ...op })} className="text-blue-700 hover:underline text-xs">
                        Bearb.
                      </button>
                      <button onClick={() => handleDelete(op)} className="text-red-500 hover:underline text-xs">
                        Löschen
                      </button>
                    </td>
                  </>
                )}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {!search && (
        <div className="flex items-center justify-center gap-4">
          <button onClick={() => handlePage(-1)} disabled={page === 0} className="text-sm text-gray-500 hover:text-gray-800 disabled:opacity-30">
            Zurück
          </button>
          <span className="text-sm text-gray-400">Seite {page + 1}</span>
          <button onClick={() => handlePage(1)} disabled={operators.length < 50} className="text-sm text-gray-500 hover:text-gray-800 disabled:opacity-30">
            Weiter
          </button>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useRef, type FormEvent } from 'react';
import { apiFetch, getOrCreateOperator } from '../services/api';
import { getSocket } from '../services/socket';
import CallsignInput, { type CallsignInputRef } from './CallsignInput';

interface Props {
  exerciseId: string;
  reports: any[];
  onReportCreated: (report: any) => void;
  onReportUpdated: (report: any) => void;
  onReportDeleted: (reportId: number) => void;
}

interface EntryForm {
  callsign: string;
  operator: any;
  rapport: string;
  notes: string;
  opName: string;
  opQth: string;
  bezirkCode: string;
  suffix?: string;
}

const SUFFIXES = ['/m', '/p', '/am', '/mm'] as const;

export default function BundMode({ exerciseId, reports, onReportCreated, onReportUpdated, onReportDeleted }: Props) {
  const [bundeslaender, setBundeslaender] = useState<any[]>([]);
  const [bezirke, setBezirke] = useState<any[]>([]);
  const [linkedRepeaters, setLinkedRepeaters] = useState<any[]>([]);
  const [blRepSelection, setBlRepSelection] = useState<Record<string, number>>({});
  const [blOpCallsigns, setBlOpCallsigns] = useState<Record<string, string>>({});
  const [blHomeRepeaters, setBlHomeRepeaters] = useState<Record<string, string>>({});
  const [collapsedBl, setCollapsedBl] = useState<Set<string>>(new Set());
  const [addRepBl, setAddRepBl] = useState<string | null>(null);
  const [newRepName, setNewRepName] = useState('');
  const [newRepFreq, setNewRepFreq] = useState('');
  const [newRepCallsign, setNewRepCallsign] = useState('');
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editForm, setEditForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '', notes: '', opName: '', opQth: '', bezirkCode: '', suffix: '' });
  const [dragReportId, setDragReportId] = useState<number | null>(null);

  useEffect(() => {
    Promise.all([
      apiFetch('/api/v1/reference/bundeslaender'),
      apiFetch('/api/v1/reference/bezirke'),
      apiFetch('/api/v1/repeaters'),
      apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`),
    ]).then(([bl, bz, allReps, exReps]) => {
      setBundeslaender(bl);
      setBezirke(bz);
      const linked = allReps.filter((r: any) => r.is_linked);
      setLinkedRepeaters(linked);
      // Initialize per-BL defaults: first linked in that BL, else first overall
      const defaults: Record<string, number> = {};
      const ops: Record<string, string> = {};
      const homeReps: Record<string, string> = {};
      for (const b of bl) {
        const inBl = linked.find((r: any) => r.bundesland_code === b.code);
        const repId = inBl ? inBl.id : (linked[0]?.id ?? 0);
        defaults[b.code] = repId;
        // Load existing OP callsign and home repeater from exercise_repeaters
        const exRep = exReps.find((er: any) => er.repeater_id === repId);
        ops[b.code] = exRep?.operator_callsign || '';
        homeReps[b.code] = exRep?.home_repeater || '';
      }
      setBlRepSelection(defaults);
      setBlOpCallsigns(ops);
      setBlHomeRepeaters(homeReps);
    }).catch(() => {});

    const socket = getSocket();
    const handleOpCallsignUpdated = (data: { exercise_id: string; repeater_id: number; operator_callsign: string }) => {
      if (data.exercise_id !== exerciseId) return;
      setBlRepSelection(sel => {
        for (const [blCode, repId] of Object.entries(sel)) {
          if (repId === data.repeater_id) {
            setBlOpCallsigns(prev => ({ ...prev, [blCode]: data.operator_callsign || '' }));
          }
        }
        return sel;
      });
    };
    const handleHomeRepeaterUpdated = (data: { exercise_id: string; repeater_id: number; home_repeater: string }) => {
      if (data.exercise_id !== exerciseId) return;
      setBlRepSelection(sel => {
        for (const [blCode, repId] of Object.entries(sel)) {
          if (repId === data.repeater_id) {
            setBlHomeRepeaters(prev => ({ ...prev, [blCode]: data.home_repeater || '' }));
          }
        }
        return sel;
      });
    };
    socket.on('op_callsign_updated', handleOpCallsignUpdated);
    socket.on('home_repeater_updated', handleHomeRepeaterUpdated);
    return () => {
      socket.off('op_callsign_updated', handleOpCallsignUpdated);
      socket.off('home_repeater_updated', handleHomeRepeaterUpdated);
    };
  }, [exerciseId]);

  const saveOpCallsign = async (blCode: string, val: string) => {
    const repId = blRepSelection[blCode];
    if (!repId) return;
    try {
      // Ensure exercise_repeater exists, then update
      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`, {
        method: 'POST',
        body: JSON.stringify({ repeater_id: repId, operator_callsign: val || null }),
      });
    } catch {
      // Already exists, just patch
      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters/${repId}`, {
        method: 'PATCH',
        body: JSON.stringify({ operator_callsign: val || null }),
      });
    }
    getSocket().emit('op_callsign_updated', { exercise_id: exerciseId, repeater_id: repId, operator_callsign: val });
  };

  const saveHomeRepeater = async (blCode: string, val: string) => {
    const repId = blRepSelection[blCode];
    if (!repId) return;
    try {
      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`, {
        method: 'POST',
        body: JSON.stringify({ repeater_id: repId, home_repeater: val || null }),
      });
    } catch {
      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters/${repId}`, {
        method: 'PATCH',
        body: JSON.stringify({ home_repeater: val || null }),
      });
    }
    getSocket().emit('home_repeater_updated', { exercise_id: exerciseId, repeater_id: repId, home_repeater: val });
  };

  const addRepeater = async (blCode: string) => {
    if (!newRepName && !newRepFreq) return;
    const name = newRepName || `Direkte ${newRepFreq}`;
    const freq = newRepFreq ? parseFloat(newRepFreq) : null;
    try {
      const rep = await apiFetch('/api/v1/repeaters', {
        method: 'POST',
        body: JSON.stringify({
          short_name: name,
          site_name: name,
          frequency_mhz: freq,
          callsign: newRepCallsign || null,
          band: freq ? (freq > 400 ? '70cm' : freq > 200 ? '23cm' : '2m') : null,
          type: 'repeater',
          bundesland_code: blCode,
        }),
      });
      setLinkedRepeaters(prev => [...prev, rep]);
      setNewRepName('');
      setNewRepFreq('');
      setNewRepCallsign('');
      setAddRepBl(null);
    } catch {}
  };

  const toggleBl = (code: string) => {
    setCollapsedBl(prev => {
      const next = new Set(prev);
      if (next.has(code)) next.delete(code); else next.add(code);
      return next;
    });
  };

  const parseRapport = (raw: string) => {
    const match = raw.match(/^(\d)\/(\d)(.*)$/);
    if (!match) return { readability: null, strength: null, db_over_s9: null };
    return {
      readability: parseInt(match[1]),
      strength: parseInt(match[2]),
      db_over_s9: match[3]?.trim() || null,
    };
  };

  const handleBezirkSubmit = async (bezirkCode: string, repeaterId: number, form: EntryForm) => {
    try {
      if (!repeaterId) return;
      const operator = await getOrCreateOperator(form.callsign, form.operator, { name: form.opName, qth: form.opQth });
      if (!operator) return;

      // Patch name/QTH if user filled them in and they differ from what's stored
      if (operator.id && (form.opName || form.opQth)) {
        const patch: any = {};
        if (form.opName && form.opName !== (operator.name || '')) patch.name = form.opName;
        if (form.opQth && form.opQth !== (operator.qth || '')) patch.qth = form.opQth;
        if (Object.keys(patch).length > 0) {
          await apiFetch(`/api/v1/operators/${operator.id}`, { method: 'PATCH', body: JSON.stringify(patch) });
        }
      }

      const parsed = parseRapport(form.rapport);

      const report = await apiFetch(`/api/v1/exercises/${exerciseId}/reports`, {
        method: 'POST',
        body: JSON.stringify({
          operator_id: operator.id,
          repeater_id: repeaterId,
          ...parsed,
          notes: form.notes || null,
          bezirk_code: (bezirkCode && bezirkCode !== '??') ? bezirkCode : null,
          suffix: form.suffix || null,
        }),
      });
      onReportCreated(report);
    } catch {
    }
  };

  const handleEdit = (report: any) => {
    setEditingId(report.id);
    setEditForm({
      callsign: report.callsign,
      operator: { id: report.operator_id, callsign: report.callsign, name: report.operator_name || null, qth: report.operator_qth || null },
      rapport: report.readability && report.strength ? `${report.readability}/${report.strength}${report.db_over_s9 || ''}` : '',
      notes: report.notes || '',
      opName: report.operator_name || '',
      opQth: report.operator_qth || '',
      bezirkCode: report.bezirk_code || '',
      suffix: report.suffix || '',
    });
  };

  const handleUpdate = async () => {
    if (!editingId) return;
    const parsed = parseRapport(editForm.rapport);
    try {
      // Save operator name/qth if changed
      if (editForm.operator?.id) {
        const nameChanged = (editForm.opName || '') !== (editForm.operator.name || '');
        const qthChanged = (editForm.opQth || '') !== (editForm.operator.qth || '');
        if (nameChanged || qthChanged) {
          const patch: any = {};
          if (nameChanged) patch.name = editForm.opName || null;
          if (qthChanged) patch.qth = editForm.opQth || null;
          await apiFetch(`/api/v1/operators/${editForm.operator.id}`, {
            method: 'PATCH',
            body: JSON.stringify(patch),
          });
        }
      }
      const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${editingId}`, {
        method: 'PATCH',
        body: JSON.stringify({ ...parsed, notes: editForm.notes || null, bezirk_code: editForm.bezirkCode || null, suffix: editForm.suffix || null }),
      });
      if (editForm.opName !== undefined) updated.operator_name = editForm.opName || null;
      if (editForm.opQth !== undefined) updated.operator_qth = editForm.opQth || null;
      onReportUpdated(updated);
      setEditingId(null);
    } catch {}
  };

  const handleMoveToBezirk = async (reportId: number, newBezirkCode: string | null) => {
    try {
      const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, {
        method: 'PATCH',
        body: JSON.stringify({ bezirk_code: newBezirkCode }),
      });
      onReportUpdated(updated);
    } catch {}
  };

  const handleDelete = async (reportId: number) => {
    if (!confirm('Rapport löschen?')) return;
    try {
      await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, { method: 'DELETE' });
      onReportDeleted(reportId);
    } catch {}
  };

  const domesticBlCodes = new Set(bundeslaender.filter(b => !b.is_international).map(b => b.code));

  return (
    <div className="space-y-2">
      {bundeslaender.filter(bl => !bl.is_international).map(bl => {
        const blBezirke = bezirke.filter(b => b.bundesland_code === bl.code);
        const defaultRepId = blRepSelection[bl.code] || 0;
        // Match reports by bezirk's Bundesland, only for linked repeaters
        const blBezirkCodes = new Set(blBezirke.map(b => b.code));
        const blReports = reports.filter(r => {
          if (!r.repeater_is_linked) return false;
          // Primary: match by bezirk code
          if (r.bezirk_code && blBezirkCodes.has(r.bezirk_code)) return true;
          // Fallback for null bezirk_code: use operator BL (if domestic), else repeater BL
          if (!r.bezirk_code) {
            const effectiveBl = domesticBlCodes.has(r.bundesland_code) ? r.bundesland_code : r.repeater_bundesland_code;
            return effectiveBl === bl.code;
          }
          return false;
        });
        const isCollapsed = collapsedBl.has(bl.code);
        const reportCount = blReports.filter(r => !r.is_op_marker && r.readability).length;

        return (
          <div key={bl.code} className="bg-white rounded-lg shadow-sm">
            <div className="bg-gray-50 px-2 sm:px-3 py-2 flex flex-wrap items-center justify-between border-b gap-1">
              <div
                onClick={() => toggleBl(bl.code)}
                className="flex items-center gap-1.5 sm:gap-2 cursor-pointer hover:bg-gray-100 rounded px-1 -mx-1 min-w-0"
              >
                <span className="text-xs text-gray-400">{isCollapsed ? '▶' : '▼'}</span>
                <span className="font-medium text-xs sm:text-sm truncate">OE{parseInt(bl.code)} {bl.name}</span>
                <span className="bg-[#0d6efd] text-white text-xs px-1.5 py-0.5 rounded-full flex-shrink-0">{reportCount}</span>
              </div>
              <div className="flex items-center gap-1.5 sm:gap-2" onClick={e => e.stopPropagation()}>
                <button
                  onClick={() => setAddRepBl(addRepBl === bl.code ? null : bl.code)}
                  className="text-xs text-gray-400 hover:text-blue-600 hidden sm:inline"
                >
                  + Umsetzer
                </button>
                <label className={`text-xs ${blOpCallsigns[bl.code] ? 'text-gray-500' : 'text-[#c8102e] font-semibold'}`}>OP:</label>
                <input
                  type="text"
                  value={blOpCallsigns[bl.code] || ''}
                  onChange={e => setBlOpCallsigns(prev => ({ ...prev, [bl.code]: e.target.value.toUpperCase() }))}
                  onBlur={e => saveOpCallsign(bl.code, e.target.value.toUpperCase())}
                  placeholder="Rufz."
                  className={`border rounded px-1.5 py-0.5 text-xs font-mono uppercase w-20 sm:w-24 focus:outline-none focus:ring-1 focus:ring-blue-500 ${blOpCallsigns[bl.code] ? 'border-gray-300' : 'border-[#c8102e] placeholder-[#c8102e]/60'}`}
                />
                <label className="text-xs text-gray-500 hidden sm:inline">REP:</label>
                <select
                  value={blHomeRepeaters[bl.code] || ''}
                  onChange={e => {
                    const val = e.target.value;
                    setBlHomeRepeaters(prev => ({ ...prev, [bl.code]: val }));
                    saveHomeRepeater(bl.code, val);
                  }}
                  className="border border-gray-300 rounded px-1 py-0.5 text-xs w-24 sm:w-32 focus:outline-none focus:ring-1 focus:ring-blue-500 hidden sm:block"
                >
                  <option value="">—</option>
                  {linkedRepeaters.filter(r => r.bundesland_code === bl.code).map(r => (
                    <option key={r.id} value={r.short_name}>{r.site_name || r.short_name}{r.band ? ` ${r.band}` : ''}</option>
                  ))}
                  {linkedRepeaters.filter(r => r.bundesland_code !== bl.code).length > 0 && (
                    <option disabled>──────</option>
                  )}
                  {linkedRepeaters.filter(r => r.bundesland_code !== bl.code).map(r => (
                    <option key={r.id} value={r.short_name}>{r.site_name || r.short_name}{r.band ? ` ${r.band}` : ''}</option>
                  ))}
                </select>
              </div>
            </div>

            {!isCollapsed && (
              <div>
                {addRepBl === bl.code && (
                  <div className="px-3 py-2 bg-blue-50 border-b flex items-center gap-1 flex-wrap">
                    <input
                      type="text"
                      value={newRepName}
                      onChange={e => setNewRepName(e.target.value)}
                      placeholder="Name"
                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-28 focus:outline-none focus:ring-1 focus:ring-blue-500"
                      autoFocus
                    />
                    <input
                      type="text"
                      value={newRepFreq}
                      onChange={e => setNewRepFreq(e.target.value)}
                      placeholder="MHz"
                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
                    />
                    <input
                      type="text"
                      value={newRepCallsign}
                      onChange={e => setNewRepCallsign(e.target.value.toUpperCase())}
                      placeholder="Rufz."
                      className="border border-gray-300 rounded px-1.5 py-0.5 text-xs font-mono uppercase w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
                    />
                    <button
                      onClick={() => addRepeater(bl.code)}
                      className="bg-green-600 hover:bg-green-700 text-white px-2 py-0.5 rounded text-xs"
                    >
                      OK
                    </button>
                    <button
                      onClick={() => { setAddRepBl(null); setNewRepName(''); setNewRepFreq(''); setNewRepCallsign(''); }}
                      className="text-gray-400 hover:text-gray-600 text-xs"
                    >
                      Abbrechen
                    </button>
                  </div>
                )}
                <div className="divide-y divide-gray-100">
                  {blBezirke.map(bz => {
                    const bzReports = blReports.filter(r => r.bezirk_code === bz.code);
                    return (
                      <BezirkRow
                        key={bz.code}
                        bezirk={bz}
                        reports={bzReports}
                        availableBezirke={blBezirke}
                        allBezirke={bezirke}
                        allBundeslaender={bundeslaender}
                        linkedRepeaters={linkedRepeaters}
                        defaultRepeaterId={defaultRepId}
                        onSubmit={(repeaterId, form) => handleBezirkSubmit(bz.code, repeaterId, form)}
                        onEdit={handleEdit}
                        onDelete={handleDelete}
                        onMoveToBezirk={handleMoveToBezirk}
                        editingId={editingId}
                        editForm={editForm}
                        onEditChange={setEditForm}
                        onEditSave={handleUpdate}
                        onEditCancel={() => setEditingId(null)}
                        dragReportId={dragReportId}
                        onDragStart={setDragReportId}
                        onDragEnd={() => setDragReportId(null)}
                      />
                    );
                  })}
                  {/* Sonstige — reports without matching bezirk + entry form */}
                  {(() => {
                    const bzCodes = new Set(blBezirke.map(b => b.code));
                    const unassigned = blReports.filter(r => !r.bezirk_code || !bzCodes.has(r.bezirk_code));
                    return (
                      <BezirkRow
                        bezirk={{ code: '??', name: 'Sonstige', is_capital: false }}
                        reports={unassigned}
                        availableBezirke={blBezirke}
                        allBezirke={bezirke}
                        allBundeslaender={bundeslaender}
                        linkedRepeaters={linkedRepeaters}
                        defaultRepeaterId={defaultRepId}
                        onSubmit={(repeaterId, form) => handleBezirkSubmit('??', repeaterId, form)}
                        onEdit={handleEdit}
                        onDelete={handleDelete}
                        onMoveToBezirk={handleMoveToBezirk}
                        editingId={editingId}
                        editForm={editForm}
                        onEditChange={setEditForm}
                        onEditSave={handleUpdate}
                        onEditCancel={() => setEditingId(null)}
                        dragReportId={dragReportId}
                        onDragStart={setDragReportId}
                        onDragEnd={() => setDragReportId(null)}
                      />
                    );
                  })()}
                </div>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

interface BezirkRowProps {
  bezirk: any;
  reports: any[];
  availableBezirke: any[];
  allBezirke: any[];
  allBundeslaender: any[];
  linkedRepeaters: any[];
  defaultRepeaterId: number;
  onSubmit: (repeaterId: number, form: EntryForm) => void;
  onEdit: (report: any) => void;
  onDelete: (id: number) => void;
  onMoveToBezirk: (reportId: number, bezirkCode: string | null) => void;
  editingId: number | null;
  editForm: EntryForm;
  onEditChange: (form: EntryForm) => void;
  onEditSave: () => void;
  onEditCancel: () => void;
  dragReportId: number | null;
  onDragStart: (reportId: number) => void;
  onDragEnd: () => void;
}

function BezirkRow({ bezirk, reports, availableBezirke, allBezirke, allBundeslaender, linkedRepeaters, defaultRepeaterId, onSubmit, onEdit, onDelete, onMoveToBezirk, editingId, editForm, onEditChange, onEditSave, onEditCancel, dragReportId, onDragStart, onDragEnd }: BezirkRowProps) {
  const [form, setForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '5/9', notes: '', opName: '', opQth: '', bezirkCode: '', suffix: '' });
  const [repeaterId, setRepeaterId] = useState(defaultRepeaterId);
  const [dragOver, setDragOver] = useState(false);
  const callsignRef = useRef<CallsignInputRef>(null);
  const rapportRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (defaultRepeaterId && !repeaterId) setRepeaterId(defaultRepeaterId);
  }, [defaultRepeaterId]);

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (!form.callsign && !form.operator) return;
    if (!repeaterId) return;
    onSubmit(repeaterId, form);
    setForm({ callsign: '', operator: null, rapport: '5/9', notes: '', opName: '', opQth: '', bezirkCode: '', suffix: '' });
    setTimeout(() => callsignRef.current?.focus(), 50);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    if (dragReportId) {
      const targetCode = bezirk.code === '??' ? null : bezirk.code;
      onMoveToBezirk(dragReportId, targetCode);
    }
  };

  const saveOperatorField = (field: 'name' | 'qth', value: string) => {
    if (!form.operator?.id) return;
    const original = field === 'name' ? (form.operator.name || '') : (form.operator.qth || '');
    if (value === original) return;
    apiFetch(`/api/v1/operators/${form.operator.id}`, {
      method: 'PATCH',
      body: JSON.stringify({ [field]: value || null }),
    }).then(() => {
      setForm(f => ({ ...f, operator: { ...f.operator, [field]: value || null } }));
    }).catch(() => {});
  };

  return (
    <div
      className={`px-2 sm:px-3 py-1.5 transition-colors ${dragOver && dragReportId ? 'bg-blue-100 ring-2 ring-blue-400 ring-inset' : ''}`}
      onDragOver={e => { if (dragReportId) { e.preventDefault(); setDragOver(true); } }}
      onDragLeave={() => setDragOver(false)}
      onDrop={handleDrop}
    >
      <div className="flex items-center gap-1.5 sm:gap-2 mb-1">
        <span className={`text-xs font-mono px-1.5 py-0.5 rounded text-white ${bezirk.code === '??' ? 'bg-[#ffc107] text-gray-800' : bezirk.is_capital ? 'bg-[#dc3545]' : 'bg-[#6c757d]'}`}>
          {bezirk.code === '??' ? '??' : bezirk.code}
        </span>
        <span className="text-xs text-gray-500 truncate">{bezirk.name}</span>
        {reports.length > 0 && <span className="text-xs text-gray-400 flex-shrink-0">({reports.length})</span>}
      </div>

      {reports.length > 0 && (
        <table className="w-full text-xs mb-1">
          <tbody>
            {reports.map((r, idx) => (
              <tr
                key={r.id}
                className={`hover:bg-blue-50 group ${dragReportId === r.id ? 'opacity-40' : ''}`}
                draggable={editingId !== r.id}
                onDragStart={e => { e.dataTransfer.effectAllowed = 'move'; onDragStart(r.id); }}
                onDragEnd={onDragEnd}
              >
                {editingId === r.id ? (
                  <td colSpan={6} className="py-0.5">
                    <div className="flex items-center gap-1 bg-blue-50 rounded p-1 flex-wrap" onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); onEditSave(); } }}>
                      <span className="font-mono font-medium">{r.callsign}</span>
                      <input value={editForm.opName} onChange={e => onEditChange({ ...editForm, opName: e.target.value })} placeholder="Name" className="border rounded px-1 py-0.5 text-xs w-16 sm:w-20 hidden sm:block" />
                      <input value={editForm.opQth} onChange={e => onEditChange({ ...editForm, opQth: e.target.value })} placeholder="QTH" className="border rounded px-1 py-0.5 text-xs w-14 sm:w-16 hidden sm:block" />
                      <input value={editForm.rapport} onChange={e => onEditChange({ ...editForm, rapport: e.target.value.toUpperCase() })} className="border rounded px-1 py-0.5 font-mono text-xs w-16 sm:w-20" autoFocus />
                      <input value={editForm.notes} onChange={e => onEditChange({ ...editForm, notes: e.target.value })} placeholder="Sonst." className="border rounded px-1 py-0.5 text-xs w-16 sm:w-20" />
                      <select
                        value={editForm.bezirkCode}
                        onChange={e => onEditChange({ ...editForm, bezirkCode: e.target.value })}
                        className="border rounded px-1 py-0.5 text-xs w-20 sm:w-24"
                        title="Bezirk"
                      >
                        <option value="">??</option>
                        {allBundeslaender.filter(b => !b.is_international).map(b => {
                          const blBz = allBezirke.filter(bz => bz.bundesland_code === b.code);
                          if (blBz.length === 0) return null;
                          return (
                            <optgroup key={b.code} label={`OE${parseInt(b.code)} ${b.name}`}>
                              {blBz.map(bz => <option key={bz.code} value={bz.code}>{bz.code} {bz.name}</option>)}
                            </optgroup>
                          );
                        })}
                      </select>
                      <button onClick={onEditSave} className="text-green-600 text-xs font-bold">OK</button>
                      <button onClick={onEditCancel} className="text-gray-400 text-xs">X</button>
                    </div>
                  </td>
                ) : (
                  <>
                    <td className="py-0.5 text-gray-400 w-4 cursor-grab">{idx + 1}</td>
                    <td className="py-0.5 cursor-pointer" onClick={() => onEdit(r)}>
                      <span className="font-mono font-medium">{r.callsign}{r.suffix || ''}</span>
                      {r.operator_name && <span className="ml-1 text-gray-500 text-xs">{r.operator_name}</span>}
                      {r.operator_qth && <span className="ml-1 text-gray-400 text-xs hidden sm:inline">{r.operator_qth}</span>}
                    </td>
                    <td className="py-0.5 text-blue-600 text-xs cursor-pointer hidden sm:table-cell" onClick={() => onEdit(r)}>{r.repeater_name || ''}</td>
                    <td className="py-0.5 font-mono text-gray-500 w-16 sm:w-24 cursor-pointer" onClick={() => onEdit(r)}>
                      {r.readability && r.strength ? `${r.readability}/${r.strength}${r.db_over_s9 || ''}` : '—'}
                    </td>
                    <td className="py-0.5 text-gray-500 cursor-pointer hidden sm:table-cell" onClick={() => onEdit(r)}>{r.notes || ''}</td>
                    <td className="py-0.5 w-4">
                      <button onClick={() => onDelete(r.id)} className="text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100">x</button>
                    </td>
                  </>
                )}
              </tr>
            ))}
          </tbody>
        </table>
      )}

      <form onSubmit={handleSubmit} className="flex items-center gap-1">
        {linkedRepeaters.length > 0 && (
          <select
            value={repeaterId || ''}
            onChange={e => setRepeaterId(parseInt(e.target.value))}
            className="border border-gray-300 rounded px-1 py-0.5 text-xs max-w-[80px] sm:max-w-none focus:outline-none focus:ring-1 focus:ring-blue-500"
          >
            {linkedRepeaters.map(r => (
              <option key={r.id} value={r.id}>
                {r.site_name || r.short_name}{r.callsign ? ` (${r.callsign})` : ''}
              </option>
            ))}
          </select>
        )}
        <CallsignInput
          ref={callsignRef}
          value={form.callsign}
          onChange={v => setForm(f => ({ ...f, callsign: v, operator: null, opName: '', opQth: '' }))}
          onSelect={op => {
            setForm(f => ({ ...f, operator: op, callsign: op.callsign, opName: op.name || '', opQth: op.qth || '' }));
            setTimeout(() => { const el = rapportRef.current; if (el) { el.focus(); el.setSelectionRange(el.value.length, el.value.length); } }, 50);
          }}
          onEnter={() => setTimeout(() => { const el = rapportRef.current; if (el) { el.focus(); el.setSelectionRange(el.value.length, el.value.length); } }, 50)}
          className="w-24 sm:w-28"
        />
        <div className="flex gap-0.5">
          {SUFFIXES.map(s => (
            <button
              key={s}
              type="button"
              onClick={() => setForm(f => ({ ...f, suffix: f.suffix === s ? '' : s }))}
              className={`px-1 py-0.5 rounded text-xs font-mono border ${form.suffix === s ? 'bg-blue-600 text-white border-blue-600' : 'bg-gray-100 text-gray-600 border-gray-300 hover:bg-gray-200'}`}
              title={s}
            >
              {s.slice(1)}
            </button>
          ))}
        </div>
        <input
          type="text"
          value={form.opName}
          onChange={e => setForm(f => ({ ...f, opName: e.target.value }))}
          onBlur={e => saveOperatorField('name', e.target.value)}
          placeholder="Name"
          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-20 sm:w-24 focus:outline-none focus:ring-1 focus:ring-blue-500 hidden sm:block"
        />
        <input
          type="text"
          value={form.opQth}
          onChange={e => setForm(f => ({ ...f, opQth: e.target.value }))}
          onBlur={e => saveOperatorField('qth', e.target.value)}
          placeholder="QTH"
          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-16 sm:w-20 focus:outline-none focus:ring-1 focus:ring-blue-500 hidden sm:block"
        />
        <input
          ref={rapportRef}
          type="text"
          value={form.rapport}
          onChange={e => setForm(f => ({ ...f, rapport: e.target.value.toUpperCase() }))}
          placeholder="5/9"
          className="border border-gray-300 rounded px-1.5 py-0.5 font-mono text-xs w-16 sm:w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
          onKeyDown={e => {
            if (e.altKey && e.key >= '1' && e.key <= '9') {
              e.preventDefault();
              setForm(f => ({ ...f, rapport: `5/${e.key}` }));
            }
          }}
        />
        <input
          type="text"
          value={form.notes}
          onChange={e => setForm(f => ({ ...f, notes: e.target.value }))}
          placeholder="Sonst."
          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs flex-1 min-w-[40px] sm:min-w-[60px] focus:outline-none focus:ring-1 focus:ring-blue-500"
        />
        <button type="submit" title="Rapport speichern (Enter)" className="bg-[#c8102e] hover:bg-[#a00d24] text-white px-2 py-0.5 rounded text-xs flex-shrink-0">
          + ↵
        </button>
      </form>
    </div>
  );
}

import { useState, useEffect, useRef, type FormEvent } from 'react';
import { apiFetch, getOrCreateOperator } from '../services/api';
import { getSocket } from '../services/socket';
import CallsignInput, { type CallsignInputRef } from './CallsignInput';

const BUNDESLAND_NAMES: Record<string, string> = {
  '01': 'OE1 Wien',
  '02': 'OE2 Salzburg',
  '03': 'OE3 Niederösterreich',
  '04': 'OE4 Burgenland',
  '05': 'OE5 Oberösterreich',
  '06': 'OE6 Steiermark',
  '07': 'OE7 Tirol',
  '08': 'OE8 Kärnten',
  '09': 'OE9 Vorarlberg',
  '10': 'Slowenien',
};

interface Props {
  exerciseId: string;
  repeaters: any[];
  reports: any[];
  simplexBezirke?: boolean;
  simplexBlCodes?: string;
  onReportCreated: (report: any) => void;
  onReportUpdated: (report: any) => void;
  onReportDeleted: (reportId: number) => void;
}

interface EntryForm {
  callsign: string;
  operator: any;
  rapport: string;
  notes: string;
  opName: string;
  opQth: string;
  bezirkCode: string;
  suffix?: string;
}

const SUFFIXES = ['/m', '/p', '/am', '/mm'] as const;

export default function LandMode({ exerciseId, repeaters, reports, simplexBezirke, simplexBlCodes, onReportCreated, onReportUpdated, onReportDeleted }: Props) {
  const [collapsedReps, setCollapsedReps] = useState<Set<number>>(new Set());
  const [opCallsigns, setOpCallsigns] = useState<Record<number, string>>({});
  const [bezirke, setBezirke] = useState<any[]>([]);
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editForm, setEditForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '', notes: '', opName: '', opQth: '', bezirkCode: '', suffix: '' });
  const [dragReportId, setDragReportId] = useState<number | null>(null);

  // Load bezirke + OP callsigns
  useEffect(() => {
    Promise.all([
      apiFetch('/api/v1/reference/bezirke'),
      apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`),
    ]).then(([bz, exReps]) => {
      setBezirke(bz);
      const ops: Record<number, string> = {};
      for (const er of exReps) {
        if (er.operator_callsign) {
          ops[er.repeater_id] = er.operator_callsign;
        }
      }
      setOpCallsigns(ops);
    }).catch(() => {});

    const socket = getSocket();
    const handleOpCallsignUpdated = (data: { exercise_id: string; repeater_id: number; operator_callsign: string }) => {
      if (data.exercise_id !== exerciseId) return;
      setOpCallsigns(prev => ({ ...prev, [data.repeater_id]: data.operator_callsign || '' }));
    };
    socket.on('op_callsign_updated', handleOpCallsignUpdated);
    return () => { socket.off('op_callsign_updated', handleOpCallsignUpdated); };
  }, [exerciseId]);

  // Group repeaters by Bundesland — exclude linked repeaters (those belong to BundMode)
  const repeatersByBl: Record<string, any[]> = {};
  const simplexRepeaters: any[] = [];
  for (const r of repeaters) {
    if (r.is_linked) continue;
    if (r.type === 'simplex') {
      simplexRepeaters.push(r);
    } else {
      const blCode = r.bundesland_code || '_other';
      if (!repeatersByBl[blCode]) repeatersByBl[blCode] = [];
      repeatersByBl[blCode].push(r);
    }
  }

  const activeBlCodes = simplexBlCodes ? simplexBlCodes.split(',').filter(Boolean) : ['01', '02', '03', '04', '05', '06', '07', '08', '09'];

  const sortedBlCodes = Object.keys(repeatersByBl).sort((a, b) => {
    if (a === '_other') return 1;
    if (b === '_other') return -1;
    return a.localeCompare(b);
  });

  const toggleRepeater = (repId: number) => {
    setCollapsedReps(prev => {
      const next = new Set(prev);
      if (next.has(repId)) next.delete(repId); else next.add(repId);
      return next;
    });
  };

  const saveOpCallsign = async (repeaterId: number, val: string) => {
    try {
      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters`, {
        method: 'POST',
        body: JSON.stringify({ repeater_id: repeaterId, operator_callsign: val || null }),
      });
    } catch {
      await apiFetch(`/api/v1/exercises/${exerciseId}/repeaters/${repeaterId}`, {
        method: 'PATCH',
        body: JSON.stringify({ operator_callsign: val || null }),
      });
    }
    getSocket().emit('op_callsign_updated', { exercise_id: exerciseId, repeater_id: repeaterId, operator_callsign: val });
  };

  const parseRapport = (raw: string) => {
    const match = raw.match(/^(\d)\/(\d)(.*)$/);
    if (!match) return { readability: null, strength: null, db_over_s9: null };
    return {
      readability: parseInt(match[1]),
      strength: parseInt(match[2]),
      db_over_s9: match[3]?.trim() || null,
    };
  };

  const handleBezirkSubmit = async (bezirkCode: string, repeaterId: number, form: EntryForm) => {
    try {
      const operator = await getOrCreateOperator(form.callsign, form.operator, { name: form.opName, qth: form.opQth });
      if (!operator) return;

      // Patch name/QTH if user filled them in and they differ from what's stored
      if (operator.id && (form.opName || form.opQth)) {
        const patch: any = {};
        if (form.opName && form.opName !== (operator.name || '')) patch.name = form.opName;
        if (form.opQth && form.opQth !== (operator.qth || '')) patch.qth = form.opQth;
        if (Object.keys(patch).length > 0) {
          await apiFetch(`/api/v1/operators/${operator.id}`, { method: 'PATCH', body: JSON.stringify(patch) });
        }
      }

      const parsed = parseRapport(form.rapport);

      const report = await apiFetch(`/api/v1/exercises/${exerciseId}/reports`, {
        method: 'POST',
        body: JSON.stringify({
          operator_id: operator.id,
          repeater_id: repeaterId,
          ...parsed,
          notes: form.notes || null,
          bezirk_code: (bezirkCode && bezirkCode !== '??') ? bezirkCode : null,
          suffix: form.suffix || null,
        }),
      });
      onReportCreated(report);
    } catch {}
  };

  const handleEdit = (report: any) => {
    setEditingId(report.id);
    setEditForm({
      callsign: report.callsign,
      operator: { id: report.operator_id, callsign: report.callsign, name: report.operator_name || null, qth: report.operator_qth || null },
      rapport: report.readability && report.strength ? `${report.readability}/${report.strength}${report.db_over_s9 || ''}` : '',
      notes: report.notes || '',
      opName: report.operator_name || '',
      opQth: report.operator_qth || '',
      bezirkCode: report.bezirk_code || '',
      suffix: report.suffix || '',
    });
  };

  const handleUpdate = async () => {
    if (!editingId) return;
    const parsed = parseRapport(editForm.rapport);
    try {
      // Save operator name/qth if changed
      if (editForm.operator?.id) {
        const nameChanged = (editForm.opName || '') !== (editForm.operator.name || '');
        const qthChanged = (editForm.opQth || '') !== (editForm.operator.qth || '');
        if (nameChanged || qthChanged) {
          const patch: any = {};
          if (nameChanged) patch.name = editForm.opName || null;
          if (qthChanged) patch.qth = editForm.opQth || null;
          await apiFetch(`/api/v1/operators/${editForm.operator.id}`, {
            method: 'PATCH',
            body: JSON.stringify(patch),
          });
        }
      }
      const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${editingId}`, {
        method: 'PATCH',
        body: JSON.stringify({ ...parsed, notes: editForm.notes || null, bezirk_code: editForm.bezirkCode || null, suffix: editForm.suffix || null }),
      });
      // Update the returned report with new name/qth so display refreshes
      if (editForm.opName !== undefined) updated.operator_name = editForm.opName || null;
      if (editForm.opQth !== undefined) updated.operator_qth = editForm.opQth || null;
      onReportUpdated(updated);
      setEditingId(null);
    } catch {}
  };

  const handleMoveToBezirk = async (reportId: number, newBezirkCode: string | null) => {
    try {
      const updated = await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, {
        method: 'PATCH',
        body: JSON.stringify({ bezirk_code: newBezirkCode }),
      });
      onReportUpdated(updated);
    } catch {}
  };

  const handleDelete = async (reportId: number) => {
    if (!confirm('Rapport löschen?')) return;
    try {
      await apiFetch(`/api/v1/exercises/${exerciseId}/reports/${reportId}`, { method: 'DELETE' });
      onReportDeleted(reportId);
    } catch {}
  };

  const renderRepeaterCard = (rep: any) => {
    const repReports = reports.filter(r => r.repeater_id === rep.repeater_id && !r.is_op_marker);
    const reportCount = repReports.filter(r => r.readability).length;
    const isCollapsed = collapsedReps.has(rep.repeater_id);
    const isSimplexGrouped = simplexBezirke && rep.type === 'simplex';
    const repBezirke = isSimplexGrouped
      ? bezirke.filter(b => activeBlCodes.includes(b.bundesland_code))
      : bezirke.filter(b => b.bundesland_code === rep.bundesland_code);

    // Group bezirke by BL for simplex grouped rendering
    const bezirkeByBl: Record<string, any[]> = {};
    if (isSimplexGrouped) {
      for (const bz of repBezirke) {
        if (!bezirkeByBl[bz.bundesland_code]) bezirkeByBl[bz.bundesland_code] = [];
        bezirkeByBl[bz.bundesland_code].push(bz);
      }
    }

    return (
      <div key={rep.repeater_id} className="bg-white rounded-lg shadow-sm">
        <div className="bg-gray-50 px-2 sm:px-3 py-2 flex flex-wrap items-center justify-between border-b gap-1">
          <div
            onClick={() => toggleRepeater(rep.repeater_id)}
            className="flex items-center gap-1.5 sm:gap-2 cursor-pointer hover:bg-gray-100 rounded px-1 -mx-1 min-w-0"
          >
            <span className="text-xs text-gray-400">{isCollapsed ? '▶' : '▼'}</span>
            <span className="font-medium text-xs sm:text-sm truncate">{rep.short_name}{rep.repeater_callsign ? ` (${rep.repeater_callsign})` : ''}</span>
            <span className="bg-[#0d6efd] text-white text-xs px-1.5 py-0.5 rounded-full flex-shrink-0">{reportCount}</span>
            {rep.frequency_mhz && (
              <span className="text-xs text-gray-400 hidden sm:inline">{rep.frequency_mhz} MHz</span>
            )}
            {rep.offset_mhz && (
              <span className="text-xs text-gray-400 hidden md:inline">({rep.offset_mhz > 0 ? '+' : ''}{rep.offset_mhz})</span>
            )}
            {rep.ctcss_hz && (
              <span className="text-xs text-gray-400 hidden md:inline">CTCSS {rep.ctcss_hz}</span>
            )}
          </div>
          <div className="flex items-center gap-1.5" onClick={e => e.stopPropagation()}>
            <label className={`text-xs ${opCallsigns[rep.repeater_id] ? 'text-gray-500' : 'text-[#c8102e] font-semibold'}`}>OP:</label>
            <input
              type="text"
              value={opCallsigns[rep.repeater_id] || ''}
              onChange={e => setOpCallsigns(prev => ({ ...prev, [rep.repeater_id]: e.target.value.toUpperCase() }))}
              onBlur={e => saveOpCallsign(rep.repeater_id, e.target.value.toUpperCase())}
              placeholder="Rufz."
              className={`border rounded px-1.5 py-0.5 text-xs font-mono uppercase w-20 sm:w-24 focus:outline-none focus:ring-1 focus:ring-blue-500 ${opCallsigns[rep.repeater_id] ? 'border-gray-300' : 'border-[#c8102e] placeholder-[#c8102e]/60'}`}
            />
          </div>
        </div>

        {!isCollapsed && (
          <div className="divide-y divide-gray-100">
            {repBezirke.length > 0 ? (
              <>
                {isSimplexGrouped ? (
                  /* Simplex grouped by BL → Bezirk */
                  <>
                    {activeBlCodes.sort().map(blCode => {
                      const blBezirke = bezirkeByBl[blCode] || [];
                      if (blBezirke.length === 0) return null;
                      const blLabel = BUNDESLAND_NAMES[blCode] || blCode;
                      return (
                        <div key={blCode}>
                          <div className="bg-gray-100 px-2 sm:px-3 py-1">
                            <span className="text-xs font-semibold text-gray-600 uppercase tracking-wide">{blLabel}</span>
                          </div>
                          {blBezirke.map(bz => {
                            const bzReports = repReports.filter(r => r.bezirk_code === bz.code);
                            return (
                              <BezirkRow
                                key={bz.code}
                                bezirk={bz}
                                reports={bzReports}
                                repeaterId={rep.repeater_id}
                                availableBezirke={repBezirke}
                                onSubmit={(form) => handleBezirkSubmit(bz.code, rep.repeater_id, form)}
                                onEdit={handleEdit}
                                onDelete={handleDelete}
                                onMoveToBezirk={handleMoveToBezirk}
                                editingId={editingId}
                                editForm={editForm}
                                onEditChange={setEditForm}
                                onEditSave={handleUpdate}
                                onEditCancel={() => setEditingId(null)}
                                dragReportId={dragReportId}
                                onDragStart={setDragReportId}
                                onDragEnd={() => setDragReportId(null)}
                              />
                            );
                          })}
                        </div>
                      );
                    })}
                    {/* Sonstige — reports without matching bezirk */}
                    {(() => {
                      const bzCodes = new Set(repBezirke.map(b => b.code));
                      const unassigned = repReports.filter(r => !r.bezirk_code || !bzCodes.has(r.bezirk_code));
                      return (
                        <BezirkRow
                          bezirk={{ code: '??', name: 'Sonstige', is_capital: false }}
                          reports={unassigned}
                          repeaterId={rep.repeater_id}
                          availableBezirke={repBezirke}
                          onSubmit={(form) => handleBezirkSubmit('??', rep.repeater_id, form)}
                          onEdit={handleEdit}
                          onDelete={handleDelete}
                          onMoveToBezirk={handleMoveToBezirk}
                          editingId={editingId}
                          editForm={editForm}
                          onEditChange={setEditForm}
                          onEditSave={handleUpdate}
                          onEditCancel={() => setEditingId(null)}
                          dragReportId={dragReportId}
                          onDragStart={setDragReportId}
                          onDragEnd={() => setDragReportId(null)}
                        />
                      );
                    })()}
                  </>
                ) : (
                  /* Normal repeater with bezirke */
                  <>
                    {repBezirke.map(bz => {
                      const bzReports = repReports.filter(r => r.bezirk_code === bz.code);
                      return (
                        <BezirkRow
                          key={bz.code}
                          bezirk={bz}
                          reports={bzReports}
                          repeaterId={rep.repeater_id}
                          availableBezirke={repBezirke}
                          onSubmit={(form) => handleBezirkSubmit(bz.code, rep.repeater_id, form)}
                          onEdit={handleEdit}
                          onDelete={handleDelete}
                          onMoveToBezirk={handleMoveToBezirk}
                          editingId={editingId}
                          editForm={editForm}
                          onEditChange={setEditForm}
                          onEditSave={handleUpdate}
                          onEditCancel={() => setEditingId(null)}
                          dragReportId={dragReportId}
                          onDragStart={setDragReportId}
                          onDragEnd={() => setDragReportId(null)}
                        />
                      );
                    })}
                    {/* Sonstige — reports without matching bezirk + entry form */}
                    {(() => {
                      const bzCodes = new Set(repBezirke.map(b => b.code));
                      const unassigned = repReports.filter(r => !r.bezirk_code || !bzCodes.has(r.bezirk_code));
                      return (
                        <BezirkRow
                          bezirk={{ code: '??', name: 'Sonstige', is_capital: false }}
                          reports={unassigned}
                          repeaterId={rep.repeater_id}
                          availableBezirke={repBezirke}
                          onSubmit={(form) => handleBezirkSubmit('??', rep.repeater_id, form)}
                          onEdit={handleEdit}
                          onDelete={handleDelete}
                          onMoveToBezirk={handleMoveToBezirk}
                          editingId={editingId}
                          editForm={editForm}
                          onEditChange={setEditForm}
                          onEditSave={handleUpdate}
                          onEditCancel={() => setEditingId(null)}
                          dragReportId={dragReportId}
                          onDragStart={setDragReportId}
                          onDragEnd={() => setDragReportId(null)}
                        />
                      );
                    })()}
                  </>
                )}
              </>
            ) : (
              /* No Bezirke — flat list with input form */
              <FlatReportRow
                reports={repReports}
                repeaterId={rep.repeater_id}
                onSubmit={(form) => handleBezirkSubmit('', rep.repeater_id, form)}
                onEdit={handleEdit}
                onDelete={handleDelete}
                editingId={editingId}
                editForm={editForm}
                onEditChange={setEditForm}
                onEditSave={handleUpdate}
                onEditCancel={() => setEditingId(null)}
              />
            )}
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="space-y-2">
      {sortedBlCodes.map(blCode => {
        const blReps = repeatersByBl[blCode];
        const label = BUNDESLAND_NAMES[blCode] || 'Sonstige';
        return (
          <div key={blCode}>
            <div className="px-1 mb-1 mt-2">
              <span className="text-xs font-semibold text-gray-500 uppercase tracking-wide">{label}</span>
            </div>
            <div className="space-y-2">
              {blReps.map(rep => renderRepeaterCard(rep))}
            </div>
          </div>
        );
      })}

      {simplexRepeaters.length > 0 && (
        <div>
          <div className="px-1 mb-1 mt-2">
            <span className="text-xs font-semibold text-gray-500 uppercase tracking-wide">Simplex</span>
          </div>
          <div className="space-y-2">
            {simplexRepeaters.map(rep => renderRepeaterCard(rep))}
          </div>
        </div>
      )}
    </div>
  );
}

interface BezirkRowProps {
  bezirk: any;
  reports: any[];
  repeaterId: number;
  availableBezirke: any[];
  onSubmit: (form: EntryForm) => void;
  onEdit: (report: any) => void;
  onDelete: (id: number) => void;
  onMoveToBezirk: (reportId: number, bezirkCode: string | null) => void;
  editingId: number | null;
  editForm: EntryForm;
  onEditChange: (form: EntryForm) => void;
  onEditSave: () => void;
  onEditCancel: () => void;
  dragReportId: number | null;
  onDragStart: (reportId: number) => void;
  onDragEnd: () => void;
}

function BezirkRow({ bezirk, reports, repeaterId, availableBezirke, onSubmit, onEdit, onDelete, onMoveToBezirk, editingId, editForm, onEditChange, onEditSave, onEditCancel, dragReportId, onDragStart, onDragEnd }: BezirkRowProps) {
  const [form, setForm] = useState<EntryForm>({ callsign: '', operator: null, rapport: '5/9', notes: '', opName: '', opQth: '', bezirkCode: '', suffix: '' });
  const [dragOver, setDragOver] = useState(false);
  const callsignRef = useRef<CallsignInputRef>(null);
  const rapportRef = useRef<HTMLInputElement>(null);

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (!form.callsign && !form.operator) return;
    onSubmit(form);
    setForm({ callsign: '', operator: null, rapport: '5/9', notes: '', opName: '', opQth: '', bezirkCode: '', suffix: '' });
    setTimeout(() => callsignRef.current?.focus(), 50);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    if (dragReportId) {
      const targetCode = bezirk.code === '??' ? null : bezirk.code;
      onMoveToBezirk(dragReportId, targetCode);
    }
  };

  const saveOperatorField = (field: 'name' | 'qth', value: string) => {
    if (!form.operator?.id) return;
    const original = field === 'name' ? (form.operator.name || '') : (form.operator.qth || '');
    if (value === original) return;
    apiFetch(`/api/v1/operators/${form.operator.id}`, {
      method: 'PATCH',
      body: JSON.stringify({ [field]: value || null }),
    }).then(() => {
      setForm(f => ({ ...f, operator: { ...f.operator, [field]: value || null } }));
    }).catch(() => {});
  };

  return (
    <div
      className={`px-2 sm:px-3 py-1.5 transition-colors ${dragOver && dragReportId ? 'bg-blue-100 ring-2 ring-blue-400 ring-inset' : ''}`}
      onDragOver={e => { if (dragReportId) { e.preventDefault(); setDragOver(true); } }}
      onDragLeave={() => setDragOver(false)}
      onDrop={handleDrop}
    >
      <div className="flex items-center gap-1.5 sm:gap-2 mb-1">
        <span className={`text-xs font-mono px-1.5 py-0.5 rounded text-white ${bezirk.code === '??' ? 'bg-[#ffc107] text-gray-800' : bezirk.is_capital ? 'bg-[#dc3545]' : 'bg-[#6c757d]'}`}>
          {bezirk.code === '??' ? '??' : bezirk.code}
        </span>
        <span className="text-xs text-gray-500 truncate">{bezirk.name}</span>
        {reports.length > 0 && <span className="text-xs text-gray-400 flex-shrink-0">({reports.length})</span>}
      </div>

      {reports.length > 0 && (
        <table className="w-full text-xs mb-1">
          <tbody>
            {reports.map((r, idx) => (
              <tr
                key={r.id}
                className={`hover:bg-blue-50 group ${dragReportId === r.id ? 'opacity-40' : ''}`}
                draggable={editingId !== r.id}
                onDragStart={e => { e.dataTransfer.effectAllowed = 'move'; onDragStart(r.id); }}
                onDragEnd={onDragEnd}
              >
                {editingId === r.id ? (
                  <td colSpan={5} className="py-0.5">
                    <div className="flex items-center gap-1 bg-blue-50 rounded p-1 flex-wrap" onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); onEditSave(); } }}>
                      <span className="font-mono font-medium">{r.callsign}</span>
                      <input value={editForm.opName} onChange={e => onEditChange({ ...editForm, opName: e.target.value })} placeholder="Name" className="border rounded px-1 py-0.5 text-xs w-16 sm:w-20 hidden sm:block" />
                      <input value={editForm.opQth} onChange={e => onEditChange({ ...editForm, opQth: e.target.value })} placeholder="QTH" className="border rounded px-1 py-0.5 text-xs w-14 sm:w-16 hidden sm:block" />
                      <input value={editForm.rapport} onChange={e => onEditChange({ ...editForm, rapport: e.target.value.toUpperCase() })} className="border rounded px-1 py-0.5 font-mono text-xs w-16 sm:w-20" autoFocus />
                      <input value={editForm.notes} onChange={e => onEditChange({ ...editForm, notes: e.target.value })} placeholder="Sonst." className="border rounded px-1 py-0.5 text-xs w-16 sm:w-20" />
                      <select
                        value={editForm.bezirkCode}
                        onChange={e => onEditChange({ ...editForm, bezirkCode: e.target.value })}
                        className="border rounded px-1 py-0.5 text-xs w-14 sm:w-16"
                        title="Bezirk"
                      >
                        <option value="">??</option>
                        {availableBezirke.map(bz => <option key={bz.code} value={bz.code}>{bz.code}</option>)}
                      </select>
                      <button onClick={onEditSave} className="text-green-600 text-xs font-bold">OK</button>
                      <button onClick={onEditCancel} className="text-gray-400 text-xs">X</button>
                    </div>
                  </td>
                ) : (
                  <>
                    <td className="py-0.5 text-gray-400 w-4 cursor-grab">{idx + 1}</td>
                    <td className="py-0.5 cursor-pointer" onClick={() => onEdit(r)}>
                      <span className="font-mono font-medium">{r.callsign}{r.suffix || ''}</span>
                      {r.operator_name && <span className="ml-1 text-gray-500 text-xs">{r.operator_name}</span>}
                      {r.operator_qth && <span className="ml-1 text-gray-400 text-xs hidden sm:inline">{r.operator_qth}</span>}
                    </td>
                    <td className="py-0.5 font-mono text-gray-500 w-16 sm:w-24 cursor-pointer" onClick={() => onEdit(r)}>
                      {r.readability && r.strength ? `${r.readability}/${r.strength}${r.db_over_s9 || ''}` : '—'}
                    </td>
                    <td className="py-0.5 text-gray-500 cursor-pointer hidden sm:table-cell" onClick={() => onEdit(r)}>{r.notes || ''}</td>
                    <td className="py-0.5 w-4">
                      <button onClick={() => onDelete(r.id)} className="text-red-400 hover:text-red-600 opacity-0 group-hover:opacity-100">x</button>
                    </td>
                  </>
                )}
              </tr>
            ))}
          </tbody>
        </table>
      )}

      <form onSubmit={handleSubmit} className="flex items-center gap-1">
        <CallsignInput
          ref={callsignRef}
          value={form.callsign}
          onChange={v => setForm(f => ({ ...f, callsign: v, operator: null, opName: '', opQth: '' }))}
          onSelect={op => {
            setForm(f => ({ ...f, operator: op, callsign: op.callsign, opName: op.name || '', opQth: op.qth || '' }));
            setTimeout(() => { const el = rapportRef.current; if (el) { el.focus(); el.setSelectionRange(el.value.length, el.value.length); } }, 50);
          }}
          onEnter={() => setTimeout(() => { const el = rapportRef.current; if (el) { el.focus(); el.setSelectionRange(el.value.length, el.value.length); } }, 50)}
          className="w-24 sm:w-28"
        />
        <div className="flex gap-0.5">
          {SUFFIXES.map(s => (
            <button
              key={s}
              type="button"
              onClick={() => setForm(f => ({ ...f, suffix: f.suffix === s ? '' : s }))}
              className={`px-1 py-0.5 rounded text-xs font-mono border ${form.suffix === s ? 'bg-blue-600 text-white border-blue-600' : 'bg-gray-100 text-gray-600 border-gray-300 hover:bg-gray-200'}`}
              title={s}
            >
              {s.slice(1)}
            </button>
          ))}
        </div>
        <input
          type="text"
          value={form.opName}
          onChange={e => setForm(f => ({ ...f, opName: e.target.value }))}
          onBlur={e => saveOperatorField('name', e.target.value)}
          placeholder="Name"
          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-20 sm:w-24 focus:outline-none focus:ring-1 focus:ring-blue-500 hidden sm:block"
        />
        <input
          type="text"
          value={form.opQth}
          onChange={e => setForm(f => ({ ...f, opQth: e.target.value }))}
          onBlur={e => saveOperatorField('qth', e.target.value)}
          placeholder="QTH"
          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs w-16 sm:w-20 focus:outline-none focus:ring-1 focus:ring-blue-500 hidden sm:block"
        />
        <input
          ref={rapportRef}
          type="text"
          value={form.rapport}
          onChange={e => setForm(f => ({ ...f, rapport: e.target.value.toUpperCase() }))}
          placeholder="5/9"
          className="border border-gray-300 rounded px-1.5 py-0.5 font-mono text-xs w-16 sm:w-20 focus:outline-none focus:ring-1 focus:ring-blue-500"
          onKeyDown={e => {
            if (e.altKey && e.key >= '1' && e.key <= '9') {
              e.preventDefault();
              setForm(f => ({ ...f, rapport: `5/${e.key}` }));
            }
          }}
        />
        <input
          type="text"
          value={form.notes}
          onChange={e => setForm(f => ({ ...f, notes: e.target.value }))}
          placeholder="Sonst."
          className="border border-gray-300 rounded px-1.5 py-0.5 text-xs flex-1 min-w-[40px] sm:min-w-[60px] focus:outline-none focus:ring-1 focus:ring-blue-500"
        />
        <button type="submit" title="Rapport speichern (Enter)" className="bg-[#c8102e] hover:bg-[#a00d24] text-white px-2 py-0.5 rounded text-xs flex-shrink-0">
          + ↵
        </button>
      </form>
    </div>
  );
}

interface FlatReportRowProps {
