interface Props {
  stats: {
    totalParticipants: number;
    totalReports: number;
    perRepeater: { short_name: string; count: number }[];
  };
}

export default function RunningTotals({ stats }: Props) {
  return (
    <div className="bg-white rounded-lg shadow-sm px-2 sm:px-4 py-2 flex flex-wrap gap-2 sm:gap-4 text-xs sm:text-sm sticky top-0 z-10 border-b">
      <div className="font-medium text-[#1e3a5f]">
        Anwesend: <span className="font-bold">{stats.totalParticipants}</span>
      </div>
      <div className="font-medium text-[#1e3a5f]">
        Rapporte: <span className="font-bold">{stats.totalReports}</span>
      </div>
      <div className="border-l border-gray-300 pl-2 sm:pl-4 flex flex-wrap gap-2 sm:gap-3">
        {stats.perRepeater.map(r => (
          <div key={r.short_name} className="text-gray-600">
            {r.short_name}: <span className="font-semibold text-gray-800">{r.count}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../hooks/useAuth';
import { apiFetch } from '../services/api';
import { EXERCISE_TYPES, DEFAULT_EXERCISE_TYPE, getShortLabel } from '../constants/exerciseTypes';
import {
  Chart as ChartJS,
  CategoryScale, LinearScale, BarElement, PointElement, LineElement,
  Title, Tooltip, Legend, Filler,
} from 'chart.js';
import { Bar, Line } from 'react-chartjs-2';

ChartJS.register(CategoryScale, LinearScale, BarElement, PointElement, LineElement, Title, Tooltip, Legend, Filler);

interface ExerciseSummary {
  id: string;
  name: string | null;
  exercise_type: string | null;
  date: string;
  participant_count: number;
  report_count: number;
}

function getQuarter(date: string): number {
  const month = new Date(date + 'T00:00:00').getMonth();
  return Math.floor(month / 3) + 1;
}

export default function DashboardPage() {
  const { admin } = useAuth();
  const navigate = useNavigate();
  const [allExercises, setAllExercises] = useState<ExerciseSummary[]>([]);
  const [selectedYear, setSelectedYear] = useState(() => new Date().getFullYear());
  const [selectedTypes, setSelectedTypes] = useState<Set<string>>(new Set());
  const [loading, setLoading] = useState(true);
  const [showCreate, setShowCreate] = useState(false);
  const [newDate, setNewDate] = useState(() => new Date().toISOString().split('T')[0]);
  const [newType, setNewType] = useState(DEFAULT_EXERCISE_TYPE);
  const [newName, setNewName] = useState('');
  const [creating, setCreating] = useState(false);

  useEffect(() => {
    apiFetch('/api/v1/exercises')
      .then(data => setAllExercises(data))
      .catch(() => {})
      .finally(() => setLoading(false));
  }, []);

  // Derive available years and filter exercises
  const availableYears = [...new Set(allExercises.map(e => new Date(e.date + 'T00:00:00').getFullYear()))].sort();
  const yearExercises = allExercises.filter(e => new Date(e.date + 'T00:00:00').getFullYear() === selectedYear);
