              <button
                onClick={downloadFullPage}
                disabled={exporting}
                className="bg-[#1e3a5f] hover:bg-[#2a4a7f] text-white px-4 py-2 rounded text-sm font-medium disabled:opacity-50"
              >
                {exporting ? 'Exportieren...' : 'Download Auswertung'}
              </button>
              <button
                onClick={async () => {
                  try {
                    const token = localStorage.getItem('token');
                    const res = await fetch(`/api/v1/reports/adif?from=${from}&to=${to}`, {
                      headers: token ? { Authorization: `Bearer ${token}` } : {},
                    });
                    if (!res.ok) throw new Error();
                    const blob = await res.blob();
                    const url = URL.createObjectURL(blob);
                    const link = document.createElement('a');
                    link.href = url;
                    link.download = `BOS-ARSA_QSOs_${from}_${to}.adi`;
                    link.click();
                    URL.revokeObjectURL(url);
                  } catch {}
                }}
                className="bg-red-700 hover:bg-red-800 text-white px-4 py-2 rounded text-sm font-medium"
              >
                Download ADIF
              </button>
            </div>
            <p className="text-xs text-gray-400 mt-2">
              ADIF-Datei kann in QRZ.com, LOTW oder andere Logbuch-Software importiert werden.
            </p>
          </div>
        </>
      )}
    </div>
  );
}

import { useState, type FormEvent } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../hooks/useAuth';

export default function LoginPage() {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      await login(username, password);
      navigate('/');
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex flex-col">
      <div className="flex-1 flex items-center justify-center">
        <div className="bg-white rounded-xl shadow-lg p-8 w-full max-w-sm">
          <img src="/bosarsa.webp" alt="BOS-ARSA" className="h-20 mx-auto mb-4 rounded" />
          <h1 className="text-2xl font-bold text-[#1e3a5f] text-center mb-1">BOS-ARSA Log</h1>
          <p className="text-sm text-gray-500 text-center mb-6">Im Sinne der Sicherheit</p>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Benutzername</label>
              <input
                type="text"
                value={username}
                onChange={e => setUsername(e.target.value)}
                className="w-full border border-gray-300 rounded-lg px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
                required
                autoFocus
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Passwort</label>
              <input
                type="password"
                value={password}
                onChange={e => setPassword(e.target.value)}
                className="w-full border border-gray-300 rounded-lg px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
                required
              />
            </div>
            {error && <p className="text-red-600 text-sm">{error}</p>}
            <button
              type="submit"
              disabled={loading}
              className="w-full bg-[#1e3a5f] hover:bg-[#2a4a7f] text-white font-medium py-2 rounded-lg disabled:opacity-50"
            >
              {loading ? 'Anmelden...' : 'Anmelden'}
            </button>
          </form>
        </div>
      </div>
      <footer className="bg-gray-100 border-t text-center py-3 text-xs text-gray-500 flex items-center justify-center gap-2 sm:gap-4 flex-wrap px-2">
        <a href="https://oeradio.at" target="_blank" rel="noopener noreferrer" className="hover:text-gray-700">oeradio.at</a>
        <span>·</span>
        <a href="https://bosarsa.oeradio.at" target="_blank" rel="noopener noreferrer" className="hover:text-gray-700">bosarsa.oeradio.at</a>
        <span>·</span>
        <Link to="/impressum" className="hover:text-gray-700">Impressum</Link>
        <span>·</span>
        <Link to="/datenschutz" className="hover:text-gray-700">Datenschutz</Link>
        <span>·</span>
        <Link to="/hilfe" className="hover:text-gray-700">Hilfe</Link>
        <span>·</span>
        <a href="https://github.com/achildrenmile/bosarsalog" target="_blank" rel="noopener noreferrer" className="hover:text-gray-700">GitHub</a>
        <span>·</span>
        <a href="https://github.com/achildrenmile/bosarsalog/releases/tag/v1.1.7" target="_blank" rel="noopener noreferrer" className="hover:text-gray-700">v1.1.7</a>
      </footer>
    </div>
  );
}

import { Routes, Route, Navigate, Link, Outlet } from 'react-router-dom';
import { AuthProvider, useAuth } from './hooks/useAuth';
import Layout from './components/Layout';
import LoginPage from './pages/LoginPage';
import DashboardPage from './pages/DashboardPage';
import ExercisePage from './pages/ExercisePage';
import ExerciseSetupPage from './pages/ExerciseSetupPage';
import OperatorsPage from './pages/OperatorsPage';
import ReportsPage from './pages/ReportsPage';
import AggregatedReportsPage from './pages/AggregatedReportsPage';
import ImpressumPage from './pages/ImpressumPage';
import DatenschutzPage from './pages/DatenschutzPage';
import HilfePage from './pages/HilfePage';

function ProtectedRoute({ children }: { children: React.ReactNode }) {
  const { token } = useAuth();
  if (!token) return <Navigate to="/login" replace />;
  return <>{children}</>;
}

function PublicLayout() {
  return (
    <div className="min-h-screen flex flex-col">
      <nav className="bg-[#1e3a5f] text-white px-2 sm:px-4 py-2 flex items-center gap-2 sm:gap-4 shadow-md">
        <Link to="/login" className="hover:text-blue-200 flex-shrink-0">
          <div className="text-base sm:text-lg font-bold tracking-wide leading-tight">BOS-ARSA Log</div>
        </Link>
      </nav>
      <main className="p-2 sm:p-4 max-w-[1600px] mx-auto flex-1 w-full">
        <Outlet />
      </main>
      <footer className="bg-gray-100 border-t text-center py-3 text-xs text-gray-500 flex items-center justify-center gap-2 sm:gap-4 flex-wrap px-2">
        <a href="https://oeradio.at" target="_blank" rel="noopener noreferrer" className="hover:text-gray-700">oeradio.at</a>
        <span>·</span>
        <a href="https://bosarsa.oeradio.at" target="_blank" rel="noopener noreferrer" className="hover:text-gray-700">bosarsa.oeradio.at</a>
        <span>·</span>
        <Link to="/impressum" className="hover:text-gray-700">Impressum</Link>
        <span>·</span>
        <Link to="/datenschutz" className="hover:text-gray-700">Datenschutz</Link>
        <span>·</span>
        <Link to="/hilfe" className="hover:text-gray-700">Hilfe</Link>
        <span>·</span>
        <a href="https://github.com/achildrenmile/bosarsalog" target="_blank" rel="noopener noreferrer" className="hover:text-gray-700">GitHub</a>
        <span>·</span>
        <a href="https://github.com/achildrenmile/bosarsalog/releases/tag/v1.1.7" target="_blank" rel="noopener noreferrer" className="hover:text-gray-700">v1.1.7</a>
      </footer>
    </div>
  );
}

function FlexLayout() {
  const { token } = useAuth();
  return token ? <Layout /> : <PublicLayout />;
}

export default function App() {
  return (
    <AuthProvider>
      <Routes>
        <Route path="/login" element={<LoginPage />} />
        <Route
          path="/"
          element={
            <ProtectedRoute>
              <Layout />
            </ProtectedRoute>
          }
        >
          <Route index element={<DashboardPage />} />
          <Route path="exercises/:id" element={<ExercisePage />} />
          <Route path="exercises/:id/setup" element={<ExerciseSetupPage />} />
          <Route path="exercises/:id/reports" element={<ReportsPage />} />
          <Route path="reports" element={<AggregatedReportsPage />} />
          <Route path="operators" element={<OperatorsPage />} />
        </Route>
        <Route element={<FlexLayout />}>
          <Route path="/impressum" element={<ImpressumPage />} />
          <Route path="/datenschutz" element={<DatenschutzPage />} />
          <Route path="/hilfe" element={<HilfePage />} />
        </Route>
      </Routes>
    </AuthProvider>
  );
}

